    /**
     * Tworzy widok dodawania nowego wydatku.
     * Zwraca listy potrzebnych encji oraz ogranicza konta
     * tylko do tych powiązanych z klientami (client_id niepuste),
     * a dla pracowników dodatkowo filtruje po ich oddziale.
     *
     * Generated by Copilot
     */
    public function create(Request $request)
    {
        $user = auth()->user();

        /* «سند صرف لعميل» من مساحة عمل الزيارة (`openDocument('expense')`):
           `?client_id=` يختار نوع السند «لعميل» وحسابَ العميل الدفتريّ سلفاً
           — كما يفعل سند القبض. بلا المعامل تبقى الشاشة كما كانت. */
        $preselectType = null;
        $preselectAccountId = null;
        if ($clientId = $request->integer('client_id')) {
            $preselectAccountId = Account::ledger()->where('client_id', $clientId)->value('id');
            $preselectType = $preselectAccountId ? 'client' : null;
        }

        // «التصنيف الافتراضي لسند صرف العميل» — يُختار سلفاً لنوع «لعميل»، وتقرؤه
        // الشاشة أيضاً حين يبدّل المستخدم النوع إلى «لعميل» بيده
        $clientDefaultCategoryId = ExpensesCategory::clientDefaultId();
        $preselectCategoryId = $preselectType === 'client' ? $clientDefaultCategoryId : null;

        $expenses_categories = ExpensesCategory::select('id', 'name')->get();
        $suppliers = Supplier::all();
        // خزائنه هو أو خزائن من يديرهم — ثم ما يجوز له **السحب** منه وحدَه:
        // كانت الشاشة تعرض خزائن الزملاء فيُملأ السند ثم يُردّ عند الحفظ
        $treasuries = $this->withdrawableTreasuryAccounts();

        // ✨ حسابات العملاء فقط (لسند الصرف "لعميل")
        // شروط صارمة: client_id != NULL + يوجد عميل فعلي + (اختياري) ضمن شجرة العملاء
        $accounts = $this->getClientAccountsForUser($user);

        // ✨ حسابات المصروفات الطرفية (leaf) للسند العام
        [$expenseLeafAccounts, $restrictExpenseAccounts, $categoryAccountMap] = $this->expenseAccountsForUser($user);

        $MainTreasury = null;
        $treasury_id = null; // إضافة متغير لتخزين معرف الخزينة

        if ($user && $user->employee_id) {
            $TreasuryEmployee = TreasuryEmployee::where('employee_id', $user->employee_id)->first();

            if ($TreasuryEmployee && $TreasuryEmployee->treasury_id) {
                $MainTreasury = Account::where('id', $TreasuryEmployee->treasury_id)->first();
                $treasury_id = $TreasuryEmployee->treasury_id; // تعيين معرف الخزينة
            } else {
                $MainTreasury = Account::find(AccountingSettings::id('main_treasury', SystemAccountIds::MAIN_TREASURY));
                $treasury_id = $MainTreasury->id ?? null; // تعيين معرف الخزينة الرئيسية
            }
        } else {
            $MainTreasury = Account::find(AccountingSettings::id('main_treasury', SystemAccountIds::MAIN_TREASURY));
            $treasury_id = $MainTreasury->id ?? null; // تعيين معرف الخزينة الرئيسية
        }

        /* والافتراضيُّ من القائمة نفسها: خزينةُ الموظف المعيَّنة قد تكون
           ممنوعةً عليه بشرط السحب، فلا يصحّ أن تُختار له سلفاً. */
        if ($MainTreasury && $treasuries->isNotEmpty() && ! $treasuries->contains('id', $MainTreasury->id)) {
            $MainTreasury = $treasuries->first();
            $treasury_id = $MainTreasury->id;
        }

        if (! $MainTreasury) {
            throw new \Exception('لا توجد خزينة متاحة. يرجى التحقق من إعدادات الخزينة.');
        }

        $taxs = TaxSitting::all();
        $account_setting = AccountSetting::where('user_id', $user->id)->first();
        $branches = Branch::all();

        // معاينة بلا استهلاك: الرقم يُحجز فعلاً عند الحفظ لا عند فتح الشاشة
        $code = $this->generateUniqueExpenseCode(consume: false);

        return view('account::finance.expenses.create', compact(
            'expenses_categories',
            'taxs',
            'treasuries',
            'accounts',
            'expenseLeafAccounts',
            'suppliers',
            'code',
            'MainTreasury',
            'treasury_id',
            'account_setting',
            'branches',
            'preselectType',
            'preselectAccountId',
            'preselectCategoryId',
            'clientDefaultCategoryId',
            'restrictExpenseAccounts',
            'categoryAccountMap'
        ));
    }

    /**
     * جلب حسابات العملاء فقط (لسند صرف "لعميل") بشروط صارمة:
     *  - client_id IS NOT NULL
     *  - يوجد عميل فعلي مرتبط (whereHas)
     *  - (اختياري) ضمن شجرة العملاء (CLIENTS_ACCOUNT) لتجنب أي حساب مشوَّش
     *  - للموظف: مفلتر بمناطق مجموعات الموظف
     * Generated by Copilot
     */
    /**
     * معرّفات شجرة «المدينون»: الجذر المضبوط في الإعدادات وكل أحفاده.
     *
     * تُستعمل في موضعين يجب ألّا يفترقا: بناءُ قائمة الاختيار في الشاشة،
     * وفحصُ ما اختير عند الحفظ. افتراقهما هو ما جعل الشاشة تعرض حساباً
     * يرفضه الخادم.
     *
     * تُعيد `null` حين لا يُعرف جذرٌ — فلا تُقيَّد القائمة ولا يُردّ الحفظ
     * على أساسٍ لا وجود له.
     *
     * @return array<int>|null
     */
    private function clientsTreeAccountIds(): ?array
    {
        static $cached = false;
        static $ids = null;

        if ($cached) {
            return $ids;
        }

        $cached = true;

        $rootId = AccountingSettings::id('clients_account', SystemAccountIds::CLIENTS_ACCOUNT);

        if (! $rootId) {
            return $ids = null;
        }

        $all = [(int) $rootId];
        $current = [$rootId];
        $safety = 0;

        while (! empty($current) && $safety < 20) {
            $children = Account::whereIn('parent_id', $current)->pluck('id')->all();

            if (empty($children)) {
                break;
            }

            $all = array_merge($all, array_map('intval', $children));
            $current = $children;
            $safety++;
        }

        return $ids = $all;
    }

    /** عامّة — تُنادَى أيضاً من Integration\Api\FinanceController (سند صرف بالجوال). */
    public function getClientAccountsForUser($user)
    {
        // معرفات شجرة المدينون — المصدر نفسه الذي يفحص به الحفظ والتعديل
        $clientsScopeIds = $this->clientsTreeAccountIds();

        /*
            **ما كان**

            الاستعلام كان يشترط `whereNotNull('client_id')` — أي لا يعرض إلا
            الحسابات المرتبطة بسجلّ عميل. فحسابات شجرة «المدينون» التي لم
            تُربَط بعميلٍ بعدُ — وهي أبناء الشجرة التي يفتحها المحاسب بيده —
            كانت تختفي كلّياً من قائمة «سند صرف لعميل»، ولا سبيل إلى
            اختيارها.

            **ما صار**

            الأساس هو شجرة الحساب المضبوط في «الحسابات المحاسبية» تحت مفتاح
            `clients_account` (المدينون): الجذر وكلّ أحفاده. ومن كان منها
            مرتبطاً بعميل يخضع لشرط أن يكون العميل نشطاً، ومن لم يُربَط
            يظهر كما هو.

            الموظّف يبقى مقيَّداً بعملائه: خطّ سيره أو مناطق مجموعاته —
            وذلك يقتضي ارتباطاً بعميل، فيُطبَّق عليه الشرط القديم.
        */
        // حاملُ «إظهار كل الحسابات في سند الصرف» يرى الشجرة كاملةً ولو كان موظفاً
        $isEmployee = $user && $user->isEmployee() && ! $this->seesAllExpenseAccounts($user);

        /*
            **نطاق «من يرى عملاء مَن»** — محورٌ إضافي فوق `$isEmployee`.

            `accessibleUserIds()` (ScopesToEmployeeHierarchy) تحسم الثلاثة:
            `null` لمن يملك `data_scope_all` أو ليس موظفاً أصلاً (مديرٌ غير
            مرتبط بحساب موظف) ⇐ بلا قيدٍ هنا يُترك للفرع القائم أدناه الذي
            يعرض شجرة المدينون كاملةً. وقائمةٌ لكل موظف: نفسه وحده إن لم يُشرف
            على أحد، أو نفسه + من يديرهم إداريّاً إن أشرف على مجموعة —
            فيُجمَع عملاء كلٍّ منهم بخوارزميته الفردية القائمة (خطّ سيره إن
            وُجد، وإلا مناطق مجموعاته) بدل تضييق الجمع على المستخدم الحالي
            وحده كما كان.
        */
        $teamUserIds = $isEmployee ? $this->accessibleUserIds() : null;

        /* «عميلٌ نشط» = غير موقوف. كان الشرط `status_id = 1` — ورقم 1 في
           جدول الحالات هو «محل مسكر» لا «نشط»، فكانت القائمة لا تعرض إلا
           عملاء المحلّات المسكّرة (ومن لا حالة له)، وتفرغ عند أغلب المنشآت.
           الموقوف يُعرف بدوره (`kpi_role = stopped`) لا برقمٍ مثبَّت. */
        $stoppedStatusIds = Statuses::stoppedClientStatusIds();
        $notStopped = function ($c) use ($stoppedStatusIds) {
            $c->whereNotIn('status_id', $stoppedStatusIds)->orWhereNull('status_id');
        };

        $query = Account::with('client')
            ->select('id', 'name', 'code', 'parent_id', 'branch_id', 'client_id', 'is_active')
            // تصفية الحسابات النشطة فقط (1 = نشط، أو فارغ)
            ->where(function ($q) {
                $q->where('is_active', 1)->orWhereNull('is_active');
            })
            ->where(function ($q) use ($isEmployee, $notStopped) {
                if ($isEmployee) {
                    // الموظف: حسابات عملائه وحدها
                    $q->whereNotNull('client_id')->whereHas('client', $notStopped);

                    return;
                }

                // غير الموظف: كل أبناء شجرة المدينون — المربوط بعميلٍ غير موقوف أو غير المربوط
                $q->whereNull('client_id')->orWhereHas('client', $notStopped);
            });

        // قصر النتائج على شجرة «المدينون» المضبوطة في الإعدادات
        if (! empty($clientsScopeIds)) {
            $query->whereIn('id', $clientsScopeIds);
        }

        /*
            الحسابات الطرفية وحدها.

            كانت الشجرة تُعرَض بجذرها «العملاء» وأيّ حسابٍ وسيط فيها — وهي
            حساباتٌ أب لا يُرحَّل إليها: رصيدها مجموعُ أبنائها، والترحيل
            المباشر إليها يُفسد الميزان. فرعُ «سند صرف عام» يمنع ذلك منذ
            البداية، وفرعُ العميل كان يسمح به.
        */
        $query->whereNotExists(function ($sub) {
            $sub->selectRaw('1')
                ->from('accounts as child')
                ->whereColumn('child.parent_id', 'accounts.id');
        });

        // نطاقي وحدي، أو نطاقي + من أشرف عليهم — `null` بلا قيدٍ (data_scope_all
        // أو مديرٌ غير مرتبط بحساب موظف)، وإلا فقائمة مستخدمين تُجمَع عملاؤهم
        if ($teamUserIds !== null) {
            $restricted = clone $query;
            $accounts = $this->restrictToTeamClients($restricted, $teamUserIds)
                ? $restricted->orderBy('code')->get()
                : collect();
        } else {
            $accounts = $query->orderBy('code')->get();
        }

        /* عميلُ زيارة مساحة العمل الجارية يُضاف دائماً — لكل مستخدم، موظّفاً
           كان أو مديراً فتح الزيارة: «سند صرف لعميل» يُفتح من داخلها
           بـ`client_id`، وكان يغيب متى لم يكن العميل في خطّ سير اليوم أو
           مناطق المجموعات. نفس قاعدة `ClientVisibilityScope`.

           باستعلامٍ مستقلّ بلا شرط الحالة: الوصول إليه فُحص عند فتح الزيارة.
           ولا شرط `is_active` كذلك: ثلثُ حسابات العملاء تحمل `is_active = 0`
           أثراً من الاستيراد، وتُرحَّل عليها الفواتير والسندات يومياً (٤٢٣
           منها بقيودٍ في آخر ٩٠ يوماً محليّاً) — فحسابُ عميل الزيارة الذي
           تصدر عليه فاتورته لا يُحجب عن سند صرفه. الطرفيّة وشجرة المدينون
           تبقيان — الحفظ يفحصهما (`store()`). */
        $openVisitClientIds = $user ? Visit::openWorkspaceClientIdsFor((int) $user->id)->all() : [];

        if ($openVisitClientIds === []) {
            return $accounts;
        }

        $visitAccounts = Account::with('client')
            ->select('id', 'name', 'code', 'parent_id', 'branch_id', 'client_id', 'is_active')
            ->whereIn('client_id', $openVisitClientIds)
            ->when(! empty($clientsScopeIds), fn ($q) => $q->whereIn('id', $clientsScopeIds))
            ->whereNotExists(function ($sub) {
                $sub->selectRaw('1')->from('accounts as child')->whereColumn('child.parent_id', 'accounts.id');
            })
            ->get();

        return $accounts
            ->merge($visitAccounts)
            ->unique('id')
            ->sortBy('code')
            ->values();
    }

    /**
     * هل يجوز لهذا المستخدم اختيار «سند صرف لمورد»؟ — قرار صاحب النظام
     * (2026-09-23). ليس حصراً على المدير (`!isEmployee()`) بل يشمل أيضاً من
     * يملك `data_scope_all` ولو كان موظفاً، والموظف الذي لا يديره أحد في
     * التسلسل الإداري (`direct_manager_id` فارغ) — أعلى الهرم الوظيفي وإن
     * كان موظفاً. مصدرٌ واحد يقرؤه `store()`/`update()` وقالبا الشاشتين.
     */
    /** عامّة — تُنادَى أيضاً من Integration\Api\FinanceController (بيانات شاشة الإنشاء بالجوال). */
    public function canExpenseToSupplier($user): bool
    {
        if (! $user || ! $user->isEmployee()) {
            return true;
        }

        if ($user->hasRolePermission('data_scope_all')) {
            return true;
        }

        return (bool) ($user->employee && is_null($user->employee->direct_manager_id));
    }

    /**
     * حراسة الحفظ المقابلة لـ getClientAccountsForUser() عرضاً: هل يقع
     * عميل هذا الحساب ضمن نطاق «عملاء الفريق» لهذا المستخدم؟ `true` دائماً
     * لمن يملك `data_scope_all` أو ليس موظفاً. تمنع إرسال `account_id`
     * يدوياً لعميلٍ خارج القائمة التي عُرضت له فعلاً.
     */
    private function clientAccountAllowedForTeam(int $accountId): bool
    {
        if ($this->seesAllExpenseAccounts(auth()->user())) {
            return true;
        }

        $teamUserIds = $this->accessibleUserIds();
        if ($teamUserIds === null) {
            return true;
        }

        $clientId = (int) Account::whereKey($accountId)->value('client_id');
        if (! $clientId) {
            return false;
        }

        $allowed = User::whereIn('id', $teamUserIds)->get()
            ->flatMap(fn ($teamUser) => $this->clientIdsForSingleEmployee($teamUser))
            // عميلُ زيارة مساحة العمل الجارية مسموحٌ أيضاً — نفس استثناء القائمة أعلاه
            ->merge(Visit::openWorkspaceClientIdsFor((int) auth()->id()))
            ->unique();

        return $allowed->contains($clientId);
    }

    /**
     * قيد فريقٍ من المستخدمين (أنا وحدي، أو أنا ومن أشرف عليهم) على حسابات
     * عملائهم: عملاءُ كلٍّ منهم بخوارزميته الفردية القائمة
     * ({@see clientIdsForSingleEmployee()}) مجموعةً باتحاد. تُرجع `false`
     * حين يخرج الاتحاد فارغاً — فلا عملاء لأحدٍ منهم.
     *
     * @param  array<int>  $userIds  معرّفات `users.id` — من accessibleUserIds()
     */
    private function restrictToTeamClients($query, array $userIds): bool
    {
        $clientIds = User::whereIn('id', $userIds)->get()
            ->flatMap(fn ($teamUser) => $this->clientIdsForSingleEmployee($teamUser))
            ->unique()
            ->values();

        if ($clientIds->isEmpty()) {
            return false;
        }

        $query->whereIn('client_id', $clientIds->all());

        return true;
    }

    /**
     * عملاءُ موظفٍ واحد: خطّ سير اليوم إن كان له صفوفٌ في الجدول (بصرف
     * النظر عن اليوم — كان الفحص هنا)، وإلا مناطق مجموعاته. الخوارزمية
     * الفردية القائمة بلا تغيير، مُستخرجةً كمعرّفات مجرَّدة كي تُجمَع عبر
     * عدّة موظفين في {@see restrictToTeamClients()}.
     *
     * @return array<int>
     */
    private function clientIdsForSingleEmployee(User $user): array
    {
        $hasVisitRoute = DB::table('employee_client_visits')->where('employee_id', $user->id)->exists();

        if ($hasVisitRoute) {
            // موظف → جلب العملاء من خط السير له في اليوم الحالي فقط (مثل الفواتير)
            $currentDate = now();
            $currentDayOfWeek = $currentDate->dayOfWeek;
            $adjustedDayOfWeek = ($currentDayOfWeek + 1) % 7;
            $englishDays = ['Saturday', 'Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'];
            $currentDayNameEn = $englishDays[$adjustedDayOfWeek];

            $startOfYear = now()->copy()->startOfYear();
            $startOfYearDay = ($startOfYear->dayOfWeek + 1) % 7;
            $daysSinceStart = $startOfYear->diffInDays($currentDate);
            $currentWeek = (int) ceil(($daysSinceStart + $startOfYearDay + 1) / 7);
            $currentYear = now()->year;

            return DB::table('employee_client_visits')
                ->where('employee_id', $user->id)
                ->where('day_of_week', $currentDayNameEn)
                ->where('week_number', $currentWeek)
                ->where('year', $currentYear)
                ->pluck('client_id')
                ->map(fn ($id) => (int) $id)
                ->all();
        }

        if (! $user->employee_id) {
            return [];
        }

        $employeeGroupIds = EmployeeGroup::where('employee_id', $user->employee_id)->pluck('group_id');
        if ($employeeGroupIds->isEmpty()) {
            return [];
        }

        return Client::whereHas('Neighborhoodname.Region', function ($q) use ($employeeGroupIds) {
            $q->whereIn('id', $employeeGroupIds);
        })->pluck('id')->map(fn ($id) => (int) $id)->all();
    }

    /**
     * أيرى هذا المستخدم كل الحسابات في سند الصرف؟ — صلاحية
     * `account.expenses.all_accounts`. بلا جدول ربط التصنيفات (ترحيلٌ لم
     * يُشغَّل) لا يُقيَّد أحد.
     */
    public function seesAllExpenseAccounts($user): bool
    {
        if (! $user || ExpensesCategory::linkedAccountMap() === null) {
            return true;
        }

        return (bool) $user->hasRolePermission('account.expenses.all_accounts');
    }

    /**
     * حسابات «سند صرف عام» لهذا المستخدم: الكلُّ لحامل الصلاحية، وحساباتُ
     * التصنيفات المربوطة وحدها لغيره (والشاشة تُظهر منها حسابات التصنيف
     * المختار). حسابُ السند الجاري تعديلُه يبقى معروضاً.
     *
     * @return array{0: Collection, 1: bool, 2: array<int, array<int>>}
     */
    public function expenseAccountsForUser($user, ?Expense $expense = null): array
    {
        $accounts = $this->getExpenseLeafAccounts();

        if ($this->seesAllExpenseAccounts($user)) {
            return [$accounts, false, []];
        }

        $map = ExpensesCategory::linkedAccountMap() ?? [];
        $allowed = array_fill_keys(array_merge(...array_values($map ?: [[]])), true);
        if ($expense && $expense->account_id) {
            $allowed[(int) $expense->account_id] = true;
        }

        return [$accounts->filter(fn ($a) => isset($allowed[(int) $a->id]))->values(), true, $map];
    }

    /**
     * حراسةُ الحفظ المقابلة: أيقع الحسابُ خارج حسابات التصنيف المختار لمن
     * لا يملك «كل الحسابات»؟ السندُ الذي لم يتغيّر حسابُه ولا تصنيفُه يمرّ.
     */
    private function expenseAccountOutsideCategory($accountId, $categoryId, ?Expense $expense = null): bool
    {
        if ($this->seesAllExpenseAccounts(auth()->user())) {
            return false;
        }

        if ($expense && (int) $expense->account_id === (int) $accountId && (int) $expense->expenses_category_id === (int) $categoryId) {
            return false;
        }

        return ! in_array((int) $accountId, ExpensesCategory::linkedAccountMap()[(int) $categoryId] ?? [], true);
    }

    /**
     * جلب الحسابات الطرفية (بلا أبناء) ضمن شجرة المصروفات.
     * يستخدمها المستخدم لاختيار الحساب الثاني في قيد سند الصرف العام.
     * Generated by Copilot
     *
     * @return Collection
     */
    /** عامّة — تُنادَى أيضاً من Integration\Api\FinanceController (سند صرف بالجوال). */
    public function getExpenseLeafAccounts()
    {
        // جذور شجرة المصروفات: SystemAccountIds::EXPENSES و OTHER_EXPENSES_PARENT
        $expenseRootIds = array_filter([
            AccountingSettings::id('expenses', SystemAccountIds::EXPENSES) ?? null,
            AccountingSettings::id('other_expenses_parent', SystemAccountIds::OTHER_EXPENSES_PARENT) ?? null,
        ]);

        if (empty($expenseRootIds)) {
            return collect();
        }

        // bfs لجمع كل الأحفاد
        $allDescendantIds = [];
        $current = $expenseRootIds;
        $safety = 0;
        while (! empty($current) && $safety < 20) {
            $children = Account::whereIn('parent_id', $current)->pluck('id')->all();
            if (empty($children)) {
                break;
            }
            $allDescendantIds = array_merge($allDescendantIds, $children);
            $current = $children;
            $safety++;
        }

        if (empty($allDescendantIds)) {
            return collect();
        }

        // فقط الحسابات الطرفية (لا تملك أبناء) من القائمة
        $parentsWithChildren = Account::whereIn('parent_id', $allDescendantIds)
            ->distinct()->pluck('parent_id')->all();
        $parentSet = array_fill_keys($parentsWithChildren, true);

        return Account::select('id', 'name', 'code', 'parent_id', 'account_type')
            ->whereIn('id', $allDescendantIds)
            ->where(function ($q) {
                $q->where('is_active', 1)->orWhereNull('is_active');
            })
            ->get()
            ->filter(function ($a) use ($parentSet) {
                return ! isset($parentSet[$a->id]); // طرفي فقط
            })
            ->sortBy(function ($a) {
                return is_numeric($a->code) ? (int) $a->code : $a->code;
            })
            ->values();
    }

    public function store(Request $request)
    {
        /*
            نقرتان على «حفظ» — أو ضغطٌ ثانٍ قبل استجابة الزرّ لأولاهما —
            كانتا تُنشئان سندي صرفٍ متطابقين فيصرفان المبلغ مرّتين.
            البصمة قبل أي `merge()` أدناه: القيم كما أرسلها المتصفّح فعلاً.
        */
        $duplicateLock = $this->guardDuplicateSubmission($request, 'expense', [
            'amount', 'date', 'expense_type', 'treasury_id', 'account_id', 'supplier_id', 'expenses_category_id', 'description',
        ]);

        /*
            مستوى المعاملة قبل الدخول.

            التحقّق أدناه يقع قبل `beginTransaction`، فحين يفشل لا معاملةَ
            لهذا الفعل تُتراجَع — و`DB::rollback()` بلا شرطٍ يُسقط عندئذٍ
            معاملةَ من ناداه: مهمّةٌ في طابور أو خدمةٌ تغلّف عدّة عمليات،
            فتضيع كتاباتٌ ناجحة سبقت هذا النداء ولا علاقة لها بفشله.
        */
        $transactionLevel = DB::transactionLevel();

        try {
            // ✨ الموظفون مقيدون بسند صرف عام أو لعميل فقط — إلا من يملك
            // `data_scope_all` أو لا يديره أحد؛ هؤلاء يُسمح لهم بـ«لمورد» أيضاً
            // (server-side enforcement, مطابقٌ لما تعرضه create.blade.php)
            $authUser = Auth::user();
            $isEmployeeUser = $authUser && $authUser->isEmployee();
            /*
                كان النوعُ يُحوَّل صامتاً إلى «عام» ثم يُردّ بـ«يجب اختيار
                الحساب الثاني للقيد» — رسالةٌ لا تقول للمستخدم إنه لا يملك
                الصرف لمورد. والشاشة تُخفي الخيار أصلاً، فلا يصل إلا بطلبٍ
                مُعدٍّ يدوياً أو من تطبيقٍ لم يقرأ `can_expense_to_supplier`.
            */
            if ($isEmployeeUser && ! $this->canExpenseToSupplier($authUser)
                && $request->input('expense_type') === 'supplier') {
                throw ValidationException::withMessages([
                    'expense_type' => ['لا تملك صلاحية «سند صرف لمورد» — اختر سند صرف عام أو لعميل.'],
                ]);
            }

            /*
                تنظيف القيم المتعارضة بحسب نوع السند.

                **ما كان**

                فرعُ «سند صرف لعميل» كان يمسح `expenses_category_id` مع
                `supplier_id`. والتصنيف ليس قيمةً متعارضة: هو تصنيفُ
                المصروف الذي تُبنى عليه تقارير «المصروفات حسب التصنيف»،
                ولا دور له في اختيار حساب القيد لهذا النوع — الحساب هو
                حساب العميل مباشرةً (انظر بناء القيد أدناه).

                فكانت الشاشة تعرض حقل التصنيف وتقبل اختياره، ثم يُمحى
                صامتاً قبل التحقّق فيُحفظ العمود فارغاً. والمستخدم يرى
                اختياره ولا يجده في السند.

                والأسوأ أن الأمر غيرُ مطّرد: سند «عام» يحتفظ بتصنيفه وسند
                «لمورد» يحتفظ بتصنيفه، والعميل وحده يفقده.

                **ما صار**

                يبقى التصنيف محفوظاً في الأنواع الثلاثة. وهو اختياري لنوع
                العميل لا إلزامي — كما يقول شرط `required_unless` أدناه —
                فمن لا يريد تصنيفاً يتركه فارغاً.

                ويبقى مسحُ ما يتعارض فعلاً: المورد لا معنى له في سندٍ عام
                أو لعميل، والحساب لا معنى له في سندٍ لمورد.
            */
            $expenseType = $request->input('expense_type', 'general');
            if ($expenseType === 'general') {
                $request->merge(['supplier_id' => null]);
            } elseif ($expenseType === 'client') {
                $request->merge(['supplier_id' => null]);
            } elseif ($expenseType === 'supplier') {
                $request->merge(['account_id' => null]);
            }

            /* سند صرف لعميل بلا تصنيف ⇒ «التصنيف الافتراضي لسند صرف العميل»
               من «تصنيفات المصروفات» — لا «غير محدد». ما اختاره المستخدم
               صراحةً يبقى كما هو. */
            if ($expenseType === 'client' && ! $request->filled('expenses_category_id')
                && ($defaultCategoryId = ExpensesCategory::clientDefaultId())) {
                $request->merge(['expenses_category_id' => $defaultCategoryId]);
            }

            // التحقق من صحة البيانات المدخلة
            // منطق محدَّث:
            //  - general: التصنيف + الحساب الثاني (account_id) مطلوبان (والحساب يجب أن يكون طرفي)
            //  - client : الحساب (account_id) مطلوب
            //  - supplier: المورد (supplier_id) مطلوب
            $validated = $request->validate([
                'amount' => 'required|numeric|min:0.01',
                'date' => 'required|date',
                'seller' => 'nullable|string|max:255',
                'expense_type' => 'required|in:general,client,supplier',
                'expenses_category_id' => 'required_unless:expense_type,client|nullable|exists:expenses_categories,id',
                'account_id' => 'required_if:expense_type,general|required_if:expense_type,client|nullable|exists:accounts,id',
                'supplier_id' => 'required_if:expense_type,supplier|nullable|exists:suppliers,id',
                'treasury_id' => 'required|exists:accounts,id',
                'cost_center_id' => 'nullable|exists:cost_centers,id',
                'description' => 'nullable|string|max:500',
                'branch_id' => 'nullable|exists:branches,id',
                'payment_method_id' => 'nullable|exists:payment_methods,id',
                'attachments' => 'nullable|array',
                'attachments.*' => 'file|mimes:jpg,jpeg,png,pdf,doc,docx,xls,xlsx|max:5120',
                // الضريبة من «إعدادات الضرائب» — معرّفٌ غير موجود كان يبلغ الحفظ فيسقط 500
                'tax1' => 'nullable|exists:tax_sittings,id',
                'tax2' => 'nullable|exists:tax_sittings,id',
                'tax1_account_id' => 'nullable|exists:accounts,id',
                'tax2_account_id' => 'nullable|exists:accounts,id',
            ], [
                'amount.required' => 'المبلغ مطلوب',
                'amount.numeric' => 'المبلغ يجب أن يكون رقماً',
                'amount.min' => 'المبلغ يجب أن يكون أكبر من صفر',
                'date.required' => 'التاريخ مطلوب',
                'expense_type.required' => 'نوع السند مطلوب',
                'expense_type.in' => 'نوع السند غير صالح',
                'expenses_category_id.required_unless' => 'التصنيف مطلوب لسند الصرف العام أو سند صرف لمورد',
                'account_id.required_if' => 'يجب اختيار الحساب الثاني للقيد',
                'supplier_id.required_if' => 'يجب اختيار المورد عند اختيار "سند صرف لمورد"',
                'treasury_id.required' => 'الخزينة مطلوبة',
                'treasury_id.exists' => 'الخزينة المحددة غير موجودة',
                'payment_method_id.exists' => 'طريقة الدفع المختارة غير معرَّفة في الإعدادات',
                'attachments.*.mimes' => 'المرفقات يجب أن تكون من نوع: jpg, jpeg, png, pdf, doc, docx, xls, xlsx',
                'attachments.*.max' => 'حجم المرفق يجب ألا يتجاوز 5 ميجابايت',
            ]);

            // «إضافة ضرائب» بلا اختيار نوعها — لا يُحفظ السند
            TaxableDocument::assertChosenWhenAdded($request->all());

            /*
                الفترة وشرط السحب **بعد** التحقّق من المدخلات: كانا قبله،
                فمن كتب المبلغ «مية» جاءه «لا يُسمح لك بالسحب من الخزينة»
                بدل «المبلغ يجب أن يكون رقماً».

                سند الصرف **سحبٌ** من الخزينة، وشرطُ السحب مضبوطٌ في شاشة
                إنشائها — فلا يصرف منها إلا من سُمح له.
            */
            $this->guardPeriod($request->input('date'));
            $this->guardTreasuryWithdraw($request->input('treasury_id'));

            // ✨ تحقق إضافي: الحساب المحدد للسند العام يجب أن يكون طرفياً (لا أبناء)
            if ($expenseType === 'general' && $request->filled('account_id')) {
                $accId = $request->input('account_id');
                if (Account::where('parent_id', $accId)->exists()) {
                    if ($request->ajax() || $request->wantsJson()) {
                        return response()->json([
                            'success' => false,
                            'message' => 'يجب اختيار حساب طرفي (بدون حسابات فرعية).',
                            'errors' => ['account_id' => ['يجب اختيار حساب طرفي (بدون حسابات فرعية).']],
                        ], 422);
                    }

                    return back()->withErrors(['account_id' => 'يجب اختيار حساب طرفي (بدون حسابات فرعية).'])->withInput();
                }

                // ✨ تحقق أمني: للموظفين - الحساب يجب أن يكون من حسابات المصروفات فقط
                if ($isEmployeeUser) {
                    $allowedExpenseAccountIds = $this->getExpenseLeafAccounts()->pluck('id')->toArray();
                    if (! in_array((int) $accId, $allowedExpenseAccountIds, true)) {
                        if ($request->ajax() || $request->wantsJson()) {
                            return response()->json([
                                'success' => false,
                                'message' => 'يُسمح للموظفين فقط باختيار حسابات المصروفات.',
                                'errors' => ['account_id' => ['يجب اختيار حساب من شجرة المصروفات.']],
                            ], 422);
                        }

                        return back()->withErrors(['account_id' => 'يجب اختيار حساب من شجرة المصروفات.'])->withInput();
                    }
                }

                // بلا «إظهار كل الحسابات في سند الصرف»: حساباتُ التصنيف المختار وحدها
                if ($this->expenseAccountOutsideCategory($accId, $request->input('expenses_category_id'))) {
                    $message = 'هذا الحساب ليس من حسابات التصنيف المختار.';

                    if ($request->ajax() || $request->wantsJson()) {
                        return response()->json(['success' => false, 'message' => $message, 'errors' => ['account_id' => [$message]]], 422);
                    }

                    return back()->withErrors(['account_id' => $message])->withInput();
                }
            }

            /*
                نوع «عميل»: الحساب يجب أن يقع في شجرة المدينون.

                **ما كان**

                الشرط `empty($acc->client_id)` — أي أن يكون الحساب مرتبطاً
                بسجلّ عميل. وحين وُسّعت قائمة الاختيار لتشمل «المدينون
                وأبناءهم» كما تعرضها الشجرة المحاسبية، صارت الشاشة تعرض
                حساباتٍ يرفضها الخادم: يختار المستخدم حساباً من القائمة
                فيُردّ بـ«يجب اختيار حساب عميل صحيح» — والحساب من القائمة
                التي عرضتها الشاشة نفسها.

                **ما صار**

                الفحص يطابق ما تعرضه القائمة: العضوية في شجرة الحساب
                المضبوط تحت `clients_account` في «الحسابات المحاسبية».
                والحساب المرتبط بعميل يقع فيها بطبيعته، فلم يُفقد شيء من
                الضبط السابق.
            */
            if ($expenseType === 'client' && $request->filled('account_id')) {
                $accId = (int) $request->input('account_id');
                $scope = $this->clientsTreeAccountIds();

                $outsideTree = $scope !== null && ! in_array($accId, $scope, true);
                $isParent = Account::where('parent_id', $accId)->exists();
                // نفس نطاق القائمة (عرضاً) يُفرض هنا (حفظاً): معرّف عميلٍ
                // مُرسَل يدوياً خارج ما يراه هذا المستخدم — راجع getClientAccountsForUser()
                $outsideTeam = ! $isParent && ! $outsideTree && Account::whereKey($accId)->exists()
                    && ! $this->clientAccountAllowedForTeam($accId);

                if (! Account::whereKey($accId)->exists() || $outsideTree || $isParent || $outsideTeam) {
                    $message = match (true) {
                        $isParent => 'يجب اختيار حساب طرفي (بدون حسابات فرعية).',
                        $outsideTeam => 'هذا الحساب خارج نطاق عملائك.',
                        default => 'يجب اختيار حساب من شجرة المدينون.',
                    };

                    if ($request->ajax() || $request->wantsJson()) {
                        return response()->json([
                            'success' => false,
                            'message' => $message,
                            'errors' => ['account_id' => [$message]],
                        ], 422);
                    }

                    return back()->withErrors(['account_id' => $message])->withInput();
                }
            }

            DB::beginTransaction();

            // إنشاء سند الصرف الجديد
            $expense = new Expense;

            // ✨ التحقق من أن الكود فريد ضد كل من: Expenses + JournalEntries (لتجنب التقاط orphan)
            $code = $request->input('code');
            $codeExists = Expense::where('code', $code)->exists() ||
                JournalEntry::where('reference_number', $code)->exists();

            if ($codeExists || empty($code)) {
                $code = $this->generateUniqueExpenseCode();
            }

            $expense->code = $code;
            $expense->created_by = auth()->id();
            $expense->amount = $request->input('amount', 0);
            $expense->description = $request->input('description');
            $expense->date = $request->input('date');
            $expense->unit_id = $request->input('unit_id');
            $expense->expenses_category_id = $request->input('expenses_category_id');
            $expense->supplier_id = $request->input('supplier_id');
            $expense->account_id = $request->input('account_id');

            // تعبئة حقل صرف إلى تلقائياً إذا لم يتم إرساله
            $seller = $request->input('seller');
            if (empty($seller)) {
                // الأولوية: المورد أولاً
                if ($request->input('supplier_id')) {
                    $supplier = Supplier::find($request->input('supplier_id'));
                    $seller = $supplier ? $supplier->trade_name : null;
                }
                // ثانياً: الحساب (العميل)
                if (empty($seller) && $request->input('account_id')) {
                    $account = Account::find($request->input('account_id'));
                    $seller = $account ? $account->name : null;
                }
                // ثالثاً: التصنيف
                if (empty($seller) && $request->input('expenses_category_id')) {
                    $category = ExpensesCategory::find($request->input('expenses_category_id'));
                    $seller = $category ? $category->name : null;
                }
            }
            $expense->seller = $seller;

            $expense->is_recurring = $request->boolean('is_recurring', false);
            $expense->recurring_frequency = $request->input('recurring_frequency');
            $expense->end_date = $request->input('end_date');
            $expense->tax1 = $request->input('tax1', 0);
            $expense->tax2 = $request->input('tax2', 0);
            $expense->tax1_account_id = $request->input('tax1_account_id');
            $expense->tax2_account_id = $request->input('tax2_account_id');

            /*
                وسمُ «سندٌ ضريبي» يُضبط من المدخلات لا بخانةٍ يؤشّرها
                المستخدم: ما يُترك لتذكّره يُنسى، فيخرج الإقرارُ ناقصاً
                بمقدار ما نُسي. والقاعدةُ في `TaxableDocument` — موضعٌ
                واحد لسندات الصرف والقبض والقيود.
            */
            $expense->is_taxable = TaxableDocument::fromVoucherInput($request->all());

            /*
                **الضريبةُ تُحسب هنا، لا تُؤخذ من الطلب.**

                كان `tax1_amount` و`total_amount` يُحفظان كما أرسلهما
                المتصفّح. فمن عبث بالطلب — أو أخطأ حسابُ الشاشة — حُفظ
                رقمُه كما هو، وخرج القيدُ والإقرارُ عليه.

                والحسابُ الآن من **معرّف الضريبة المحفوظ**: النسبةُ
                وطريقتُها من «إعدادات الضرائب» لا من الشاشة.

                **والطريقة المصرية:** الإجمالي يشمل الضريبة دائماً، و`amount`
                يُخزَّن **أساساً قبل الضريبة**. فإن كانت الضريبة «شاملة»
                (`included`) كان ما أدخله المستخدم حاملاً لها، فتُستخرَج منه
                ويُردّ المبلغُ إلى أساسه؛ وإن كانت «مضافة» (`excluded`) فما
                أدخله هو الأساسُ نفسه. وباستقرار `amount` على الأساس يصحّ
                سطرُ الحساب المقابل في القيد، ويصحّ مجموعُ التقارير:
                `total_amount = amount + الضريبة` في الحالَين.
            */
            $taxLines = TaxCalculator::forDocument($expense->amount, $expense->tax1, $expense->tax2);

            $expense->amount = $taxLines['base'];
            $expense->tax1_amount = $taxLines['tax1'];
            $expense->tax2_amount = $taxLines['tax2'];
            $expense->total_amount = $taxLines['total'];

            /*
                مركز التكلفة اختياري ولا يُخزَّن في السند.

                جدول `expenses` لا يحمل إلا رايةً (`cost_centers_enabled`)؛
                المركز نفسه يسكن سطور القيد منذ هجرة
                `move_cost_center_to_journal_entry_details`. فالحقل الجديد
                يمرّ من النموذج إلى القيد مباشرةً، والرايةُ تُرفع لتَعلم
                الشاشة أنّ السند موزَّع.
            */
            $costCenterId = $request->filled('cost_center_id')
                ? (int) $request->input('cost_center_id')
                : null;

            $expense->cost_centers_enabled = $costCenterId !== null;

            // تحديد الفرع - للموظف نستخدم فرعه دائماً، للمدير يمكنه الاختيار
            $user = Auth::user();
            $isAdmin = $user && ! $user->isEmployee();

            if ($isAdmin) {
                // المدير يمكنه اختيار الفرع، وإذا لم يختر نستخدم فرعه
                $branchId = $request->input('branch_id');
                if (empty($branchId)) {
                    $branchId = $user->branch_id ?? null;
                }
            } else {
                // الموظف: نستخدم فرعه دائماً بغض النظر عن القيمة المرسلة
                $branchId = $user->branch_id ?? null;
            }
            $expense->branch_id = $branchId;
            // طريقة الدفع من شاشة الإعدادات — اختيارية، فقد لا تُسجَّل
            $expense->payment_method_id = $request->input('payment_method_id') ?: null;

            /*
                تحديد الخزينة.

                كان الموظف مقفلاً على خزينته المعيَّنة له وحدها — لا خزينة
                من يديرهم، ولا يملك اختياراً إطلاقاً. الآن يُقبل ما أرسله
                الطلب (المدير أو الموظف) بعد التحقّق من نطاقه:
                `assertTreasuryAccess()` تتجاوز الفحص كلياً للمدير أو من
                يملك `data_scope_all`، وتقصر الموظف على خزينته وخزائن من
                يديرهم (`treasury_employees` + التسلسل الإداري). إن لم
                يُرسَل شيء تُستعمَل خزينته الافتراضية.
            */
            $requestedTreasuryId = $request->input('treasury_id');

            if (! empty($requestedTreasuryId)) {
                $this->assertTreasuryAccess((int) $requestedTreasuryId);
                $expense->treasury_id = $requestedTreasuryId;
            } else {
                $userTreasuryId = null;
                if ($user && $user->employee_id) {
                    $te = TreasuryEmployee::where('employee_id', $user->employee_id)->first();
                    if ($te && $te->treasury_id) {
                        $userTreasuryId = $te->treasury_id;
                    }
                }
                $expense->treasury_id = $userTreasuryId ?: AccountingSettings::id('main_treasury', SystemAccountIds::MAIN_TREASURY);
            }

            // رفع المرفقات إذا وجدت (دعم ملفات متعددة)
            if ($request->hasFile('attachments')) {
                $attachmentPaths = [];
                foreach ($request->file('attachments') as $file) {
                    $fileName = $this->uploadImage('assets/uploads/expenses', $file);
                    $attachmentPaths[] = 'assets/uploads/expenses/'.$fileName;
                }
                $expense->attachments = json_encode($attachmentPaths);
            }

            // حفظ سند الصرف
            $expense->save();

            // تسجيل العملية في السجلات
            OperationLog::record(
                'created',
                'expense',
                $expense->id,
                sprintf('تم انشاء سند صرف رقم **%s** بقيمة **%s**', $expense->code, number_format($expense->amount, 2))
            );

            // الحصول على الخزينة المناسبة
            $treasuryAccount = Account::find($expense->treasury_id);
            if (! $treasuryAccount) {
                throw new \Exception('لا توجد خزينة متاحة. يرجى التحقق من إعدادات الخزينة.');
            }

            // الإجمالي شامل الضرائب — كما حُسب عند الحفظ، لا جمعٌ يُعاد
            $tax1Amount = (float) $expense->tax1_amount;
            $tax2Amount = (float) $expense->tax2_amount;
            $totalAmountWithTax = (float) $expense->total_amount;

            // التحقق من رصيد الخزينة (شامل الضرائب)
            if ($treasuryAccount->balance < $totalAmountWithTax) {
                throw ValidationException::withMessages(['amount' => ['رصيد الخزينة غير كافٍ لتنفيذ عملية الصرف.']]);
            }

            // ⚠️ ملاحظة هامة: لا نحدِّث رصيد الخزينة يدوياً هنا.
            // boot() في JournalEntryDetail يحدِّث الأرصدة تلقائياً عند إنشاء التفاصيل.

            // ✨ المنطق الجديد: نستخدم الحساب الذي اختاره المستخدم مباشرة - لا توليد ضمني
            $expenseType = $request->input('expense_type', 'general');
            $selectedAccountId = $request->input('account_id');
            $selectedSupplierId = $request->input('supplier_id');
            $selectedCategoryId = $request->input('expenses_category_id');

            $accountIdToUse = null;
            $journalDescription = $expense->description ?: 'سند صرف';

            if ($expenseType === 'supplier') {
                // سند صرف لمورد - نستخدم حساب المورد (نُنشئ إن لم يوجد)
                //
                // **علّة كانت تُسقط كل سند صرفٍ لمورد يُستخدم لأول مرة**:
                // `suppliers.account_id` عمودٌ لا وجود له في الجدول — الربط
                // الحقيقي عكسي (`accounts.supplier_id`، انظر Supplier::account()).
                // فكتابة `$supplier->account_id = …; $supplier->save();` بعد
                // إنشاء الحساب كانت تُسقط الطلب بخطأ SQL خام «Unknown column
                // account_id»، رغم أن الحساب نفسه أُنشئ بربطٍ صحيح
                // (`supplier_id` عليه) ولا حاجة لحفظ أي شيء على المورد إطلاقاً.
                $supplier = Supplier::with('account')->findOrFail($selectedSupplierId);
                if ($supplier->account) {
                    $accountIdToUse = $supplier->account->id;
                } else {
                    // إنشاء حساب جديد للمورد تحت حساب الموردين
                    $supplierAccount = new Account;
                    $supplierAccount->name = $supplier->trade_name ?? trim(($supplier->first_name ?? '').' '.($supplier->last_name ?? ''));
                    $supplierAccount->type = 'sub';
                    $supplierAccount->balance = 0;
                    $supplierAccount->is_active = 1;
                    $supplierAccount->code = $this->generateNextCode();
                    $supplierAccount->supplier_id = $supplier->id;
                    $supplierAccount->parent_id = AccountingSettings::id('suppliers', SystemAccountIds::SUPPLIERS);
                    $supplierAccount->balance_type = 'credit';
                    $supplierAccount->save();
                    $accountIdToUse = $supplierAccount->id;
                }
                $journalDescription = 'سند صرف لمورد: '.($supplier->trade_name ?? ($supplier->first_name ?? ''));
            } elseif ($expenseType === 'client') {
                // سند صرف لعميل - الحساب المحدد هو حساب العميل
                $clientAccount = Account::findOrFail($selectedAccountId);
                $accountIdToUse = $clientAccount->id;
                $journalDescription = 'سند صرف لعميل: '.$clientAccount->name;
            } else {
                // ✨ سند صرف عام - نستخدم الحساب الذي اختاره المستخدم مباشرة (طرفي)
                $expenseAccount = Account::findOrFail($selectedAccountId);
                $accountIdToUse = $expenseAccount->id;
                $categoryName = $selectedCategoryId
                    ? (ExpensesCategory::find($selectedCategoryId)->name ?? '')
                    : '';
                $journalDescription = 'سند صرف'.($categoryName ? ' - '.$categoryName : '')
                    .': '.$expenseAccount->name
                    .($expense->description ? ' ('.$expense->description.')' : '');
            }

            if (! $accountIdToUse) {
                throw new \Exception('لم يتم تحديد الحساب الثاني للقيد.');
            }

            // ✨ إنشاء قيد اليومية - ربط مزدوج: reference_id + reference_number
            $journalEntry = JournalEntry::create([
                'reference_number' => $expense->code,
                'reference_id' => $expense->id, // ربط قوي بمعرّف السند
                'date' => $expense->date,
                'description' => $journalDescription,
                'status' => 1,
                'currency' => $expense->documentCurrency(),
                'created_by_employee' => Auth::id(),
                'reference_type' => ReferenceType::EXPENSES,
                'linking_type' => LinkingType::SINGLE,
                'branch_id' => $expense->branch_id,
            ]);

            // تفاصيل القيد اليومي (من الخزينة - دائن بالإجمالي شامل الضرائب)
            JournalEntryDetail::create([
                'journal_entry_id' => $journalEntry->id,
                'account_id' => $treasuryAccount->id,
                'description' => 'صرف مبلغ من الخزينة',
                'debit' => 0,
                'credit' => $totalAmountWithTax,
                'is_debit' => false,
            ]);

            // تفاصيل القيد اليومي (إلى الحساب المحدد - مدين بالمبلغ الأساسي)
            JournalEntryDetail::create([
                'journal_entry_id' => $journalEntry->id,
                'account_id' => $accountIdToUse,
                'description' => $journalDescription,
                'debit' => $expense->amount,
                'credit' => 0,
                'is_debit' => true,
                // مركز التكلفة يسكن السطر المدين وحده: الخزينة مصدرُ النقد
                // لا وجهةُ الكلفة، فتحميلها المركزَ يُضاعف الرقم في التقرير
                'cost_center_id' => $costCenterId,
            ]);

            /*
                **سطرا الضريبة لا يجوز أن يسقطا.**

                الخزينة تُحمَّل دائناً بالمبلغ **شاملاً الضريبة**، بينما كان
                سطرُ الضريبة المدين مشروطاً بأن يكون المستخدم قد اختار حساباً
                لها. فمن أدخل ضريبةً ولم يختر حسابها خرج قيدُه **غير متوازن**
                بمقدارها بالضبط — وهو ما تُظهره لوحة الحسابات في «قيود غير
                متوازنة»، ويفسد كل تقريرٍ بعده بصمت.

                الحساب يُلتمس الآن من «الحسابات المحاسبية» (`vat_paid` —
                ضريبة المشتريات المدفوعة، وهي الوجهة الصحيحة لضريبة مصروف)
                متى لم يختره المستخدم. وإن تعذّر ذلك أيضاً رُمي الخطأ بدل
                حفظ قيدٍ مختلّ: مستندٌ يُرفض خيرٌ من دفترٍ يفسد.
            */
            $resolveTaxAccount = function ($chosen) {
                if ($chosen && Account::whereKey($chosen)->exists()) {
                    return (int) $chosen;
                }

                $fallback = AccountingSettings::id('vat_paid', SystemAccountIds::VAT_PAID);

                if (! $fallback || ! Account::whereKey($fallback)->exists()) {
                    throw new \RuntimeException(
                        'تعذّر تحديد حساب الضريبة: اختر حساباً للضريبة في السند، '
                        .'أو اضبط «ضريبة المشتريات المدفوعة» في الحسابات المحاسبية.'
                    );
                }

                return (int) $fallback;
            };

            foreach ([
                [$tax1Amount, $expense->tax1_account_id, 'الضريبة الأولى'],
                [$tax2Amount, $expense->tax2_account_id, 'الضريبة الثانية'],
            ] as [$taxAmount, $chosenAccount, $taxLabel]) {
                if ($taxAmount <= 0) {
                    continue;
                }

                JournalEntryDetail::create([
                    'journal_entry_id' => $journalEntry->id,
                    'account_id' => $resolveTaxAccount($chosenAccount),
                    'description' => 'ضريبة القيمة المضافة - '.$taxLabel,
                    'debit' => $taxAmount,
                    'credit' => 0,
                    'is_debit' => true,
                    'cost_center_id' => $costCenterId,
                ]);
            }

            // === معالجة نقاط سند الصرف (payment_voucher) ===
            // فقط إذا كان المستخدم موظفاً (لديه employee_id). ونسخةُ «سند
            // مكرَّر» يُصدرها `RecurringVoucherGenerator` بلا نقاط: لم يصرف
            // الموظفُ شيئاً بيده، والمهمّةُ هي التي أصدرتها باسمه
            $user = Auth::user();
            if ($user->employee_id && ! RecurringVoucherGenerator::isGenerating($request)) {
                try {
                    // تحديد client_id من حساب العميل إن وجد
                    $clientId = null;
                    if ($expense->account_id) {
                        $expAccount = Account::find($expense->account_id);
                        $clientId = $expAccount->client_id ?? null;
                    }

                    $pointsContext = [
                        'employee_id' => $user->employee_id,
                        'client_id' => $clientId,
                        'amount' => $expense->amount,
                        'branch_id' => $expense->branch_id,
                        'reference_type' => Expense::class,
                        'reference_id' => $expense->id,
                        'description' => 'سند صرف رقم '.$expense->code,
                    ];
                    app(PointsService::class)->processAction('payment_voucher', $pointsContext);
                } catch (\Throwable $e) {
                    // النقاط أثرٌ جانبي: لا تُسقط السند، لكنّها تُسجَّل حيث تُرى
                    $this->recordFailure($e, 'finance_log', 'expense_points', $expense);
                }
            }

            DB::commit();

            // إذا كان الطلب AJAX
            if ($request->ajax() || $request->wantsJson()) {
                return response()->json([
                    'success' => true,
                    'message' => 'تم إضافة سند صرف بنجاح!',
                    'redirect' => route('expenses.index'),
                ]);
            }

            return redirect()->route('expenses.index')->with('success', 'تم إضافة سند صرف بنجاح!');
        } catch (ValidationException $e) {
            // تحقّقٌ مرفوض ليس تكراراً فعلياً — يُفكّ القفل فوراً ليعيد
            // المندوب المحاولة بعد تصحيح البيانات بلا انتظار مهلته
            $duplicateLock->release();

            if (DB::transactionLevel() > $transactionLevel) {
                DB::rollback();
            }

            Log::error('خطأ في التحقق من البيانات: '.json_encode($e->errors()));

            if ($request->ajax() || $request->wantsJson()) {
                return response()->json([
                    'success' => false,
                    'message' => 'خطأ في البيانات المدخلة',
                    'errors' => $e->errors(),
                ], 422);
            }

            return back()
                ->withErrors($e->errors())
                ->withInput();
        } catch (\Exception $e) {
            // فشل الحفظ فعلاً: يُفكّ القفل فوراً ليعيد المندوب المحاولة
            $duplicateLock->release();

            // يبلغ جدول «سجلّ الأخطاء»، لا ملفّ اللوق وحده
            OperationLog::failure($e, 'Account.Expenses', 'store');

            if (DB::transactionLevel() > $transactionLevel) {
                DB::rollback();
            }

            Log::error('خطأ في إضافة سند صرف: '.$e->getMessage());
            Log::error('Stack trace: '.$e->getTraceAsString());

            if ($request->ajax() || $request->wantsJson()) {
                // بلوغ حدّ الباقة قاعدةُ عملٍ لا عطل — 402 كوسيط plan.limit
                if ($e instanceof PlanLimitExceededException) {
                    return response()->json(['success' => false, 'message' => $e->getMessage(), 'code' => 'PLAN_LIMIT_REACHED'], 402);
                }

                return response()->json([
                    'success' => false,
                    'message' => 'حدث خطأ أثناء إضافة سند الصرف: '.$e->getMessage(),
                    'error_details' => $e->getMessage(),
                ], 500);
            }

            return back()
                ->with('error', 'حدث خطأ أثناء إضافة سند الصرف: '.$e->getMessage())
                ->withInput();
        }
    }

    private function generateNextCode()
    {
        $lastAccount = Account::where('code', 'LIKE', 'account-%')
            ->orderBy(DB::raw('CAST(SUBSTRING(code, 9) AS UNSIGNED)'), 'desc')
            ->first();

        $nextNumber = $lastAccount
            ? intval(substr($lastAccount->code, 8)) + 1
            : 1;

        return 'account-'.$nextNumber;
    }

    /**
     * سببُ منع التصرّف في سندٍ أنشأه صرفُ راتب — أو `null` إن كان سنداً عاديّاً.
     *
     * سندُ الراتب ليس مستنداً قائماً بذاته. `payroll_runs` يشير إليه
     * بـ`expense_id`، وقيدُ صرفه مكتوبٌ بـ`reference_type = EXPENSES`
     * و`reference_id = expenses.id` — أي بالضبط ما يبحث عنه
     * `findExpenseJournalEntry()` أدناه. فالحذفُ من هذه الشاشة يرحّل قيداً
     * عكسيّاً **لقيد الراتب**، ثمّ يحذف الصفَّ حذفاً صلباً (`Expense` بلا
     * `SoftDeletes`) — وتبقى الصرفةُ `disbursed` تشير إلى صفٍّ محذوف،
     * وتبقى السلفُ والخصمياتُ مسوّاةً كأنّ الراتب صُرف.
     *
     * وأسوأُ من ذلك أنّ `PayrollReversalService::reverseJournals()` يتخطّى
     * كلَّ قيدٍ `is_reversed`. فمن عكَس الصرفةَ بعد ذلك من شاشتها لا يجد
     * قيداً يعكسه، وتعود الصرفةُ إلى `pending` بلا فكِّ تسوياتها: قابلةً
     * للصرف مرّةً ثانية.
     *
     * فالمخرجُ الصحيح واحدٌ لا بديل له: «عكس الصرف» من سجل صرف الرواتب،
     * فهو يرحّل القيودَ العكسية ويفكّ التسوياتَ ويعيد الحالةَ معاً في
     * معاملةٍ واحدة.
     *
     * والحصرُ على الصرفات القائمة: بعد العكس يُصفَّر `expense_id`
     * (`PayrollReversalService`)، فالسندُ الموسوم `[معكوس]` يعود إلى
     * التصرّف العاديّ ولا يُقفَل إلى الأبد.
     *
     * @param  int|string  $expenseId
     */
    private function payrollExpenseBlockReason($expenseId): ?string
    {
        $runId = PayrollRun::query()->where('expense_id', $expenseId)->value('id');

        if (! $runId) {
            return null;
        }

        return sprintf(
            'هذا السند أنشأه صرفُ راتب (عملية الصرف رقم %d)، فلا يُعدَّل ولا يُحذف من شاشة المصروفات. '.
            'استخدم «عكس الصرف» في «سجل صرف الرواتب»: يُرحَّل القيد العكسي وتُفكّ تسوية السلف والخصميات وتعود الصرفة قابلةً للتصحيح معاً.',
            $runId
        );
    }

    /**
     * البحث عن القيد المحاسبي المرتبط بسند الصرف بشكل موثوق.
     * Generated by Copilot
     *
     * المنطق:
     *  1) reference_id (مفتاح أساسي - دقيق ومضمون) ← يستخدمه أي قيد منشأ بعد إصلاح الـ controller
     *  2) Fallback (بيانات قديمة): reference_number = code، لكن:
     *      - reference_id IS NULL (لتجنب التقاط قيد سند آخر)
     *      - وليس قيد عكسي (-REV)
     *      - الأحدث (id desc) - يفضّل القيد الأصلي على المُلغى
     *
     * @param  Expense  $expense
     * @return JournalEntry|null
     */
    private function findExpenseJournalEntry($expense)
    {
        // ✅ Priority 1: ربط قوي عبر reference_id
        $entry = JournalEntry::with(['details.account'])
            ->where('reference_type', ReferenceType::EXPENSES)
            ->where('reference_id', $expense->id)
            ->orderByDesc('id')
            ->first();

        if ($entry) {
            return $entry;
        }

        // ⚠️ Priority 2: Fallback لبيانات قديمة فقط (orphan code)
        // نستثني الـ -REV ونحصر بـ reference_id IS NULL لتجنب الـ orphan لسندات لاحقة
        return JournalEntry::with(['details.account'])
            ->where('reference_type', ReferenceType::EXPENSES)
            ->where('reference_number', $expense->code)
            ->whereNull('reference_id')
            ->where('reference_number', 'NOT LIKE', '%-REV')
            ->orderByDesc('id')
            ->first();
    }

    /**
     * توليد كود سند صرف فريد لا يتعارض مع:
     *  - أي سند صرف موجود (Expense.code)
     *  - أي قيد محاسبي قديم/نشط (JournalEntry.reference_number) - يمنع التقاط orphan لاحقاً
     * Generated by Copilot
     */
    private function generateUniqueExpenseCode(bool $consume = true): string
    {
        /*
            الرقم من شاشة «ترقيم المستندات» — قسم `expense`.

            **عطلان كانا هنا**

            1) `next()` تستهلك الرقم فعلاً. وكانت تُنادى من `create()` أي عند
               مجرّد **فتح** شاشة الإضافة — فمن يفتح الشاشة ثم يتراجع يحرق
               رقماً، وتظهر فجوات في تسلسل السندات. `peek()` تعاين بلا
               استهلاك، وهي المناسبة للعرض؛ و`next()` تُستدعى عند الحفظ.

            2) عند اصطدام الرقم بسندٍ أو قيدٍ قائم، كانت الزيادة تعيد بناء
               الكود بالبادئة `EXP-` **مكتوبةً في الشيفرة** وبأربع خانات
               ثابتة — فتُهدر البادئة والتنسيق المضبوطَين في الإعدادات:
               من ضبط `PV-2026-0001` يحصل على `EXP-0002` عند أوّل تعارض.
               صارت الزيادة تحفظ ما قبل الأرقام الأخيرة وتزيدها بطولها نفسه.
        */
        $code = $consume ? next_document_number('expense') : peek_document_number('expense');

        $safety = 0;
        while ($safety < 10000 && (
            Expense::where('code', $code)->exists() ||
            JournalEntry::where('reference_number', $code)->exists()
        )) {
            $code = $this->bumpTrailingNumber($code);
            $safety++;
        }

        return $code;
    }

    /**
     * زيادة المقطع الرقمي الأخير في الكود مع الحفاظ على بادئته وطول أرقامه.
     *
     * `PV-2026-0007` → `PV-2026-0008`،  `EXP-0099` → `EXP-0100`.
     */
    private function bumpTrailingNumber(string $code): string
    {
        if (! preg_match('/^(.*?)(\d+)$/', $code, $m)) {
            return $code.'-1';
        }

        $next = (string) ((int) $m[2] + 1);

        return $m[1].str_pad($next, strlen($m[2]), '0', STR_PAD_LEFT);
    }

    public function cancel($id)
    {
        /*
            الإلغاء ليس حذفاً: يُرحَّل **قيدٌ عكسي** بتاريخ اليوم. فهو كتابةٌ
            محاسبية كاملة تلزمها حراسة الفترة كما تلزم الإنشاء — وكانت
            وحدها بلا حارس بين دوالّ هذا الملفّ.

            والحارس بتاريخ اليوم لا بتاريخ السند الأصلي: القيد العكسي
            يُرحَّل اليوم، فإقفال الشهر الجاري هو ما يمنعه.
        */
        $this->guardPeriod(now()->toDateString());

        /*
            سندُ راتبٍ مصروف لا يُلغى من هنا — انظر `payrollExpenseBlockReason()`.
            والفحصُ **قبل** `try`: ما داخلها يُلتقط بـ`catch (\Exception)`
            فيُطمس السببُ تحت «حدث خطأ أثناء الحذف».
        */
        if ($payrollBlock = $this->payrollExpenseBlockReason($id)) {
            if (request()->ajax() || request()->wantsJson()) {
                return response()->json(['success' => false, 'message' => $payrollBlock], 422);
            }

            return back()->with('error', $payrollBlock);
        }

        /*
            وسندٌ عُكس مرّةً لا يُعكس ثانية: قيدُه الأصليّ موسومٌ
            `is_reversed`، فلا يجد `findExpenseJournalEntry()` ما يعكسه —
            ويخرج الحذفُ بقيدٍ عكسيٍّ ثانٍ أو بلا قيدٍ أصلاً.
        */
        if (Expense::whereKey($id)->whereNotNull('reversed_at')->exists()) {
            $reversedBlock = 'هذا السند معكوسٌ مسبقاً وقيدُه صُحِّح بقيدٍ عكسي — لا يُعكس مرّةً أخرى.';

            if (request()->ajax() || request()->wantsJson()) {
                return response()->json(['success' => false, 'message' => $reversedBlock], 422);
            }

            return back()->with('error', $reversedBlock);
        }

        try {
            DB::beginTransaction();

            $user = Auth::user();
            $expense = Expense::findOrFail($id);

            // التحقق من النطاق - المدير يمكنه إلغاء أي سند، الموظف فقط سنداته (أو سندات من يديرهم)
            $accessibleUserIds = $this->accessibleUserIds();
            if ($accessibleUserIds !== null && ! in_array((int) $expense->created_by, $accessibleUserIds, true)) {
                if (request()->ajax() || request()->wantsJson()) {
                    return response()->json(['success' => false, 'message' => 'ليس لديك صلاحية لإلغاء هذا المصروف'], 403);
                }
                abort(403, 'ليس لديك صلاحية لإلغاء هذا المصروف');
            }

            // ✨ جلب القيد المحاسبي الأصلي - reference_id موثوق
            $originalJournalEntry = $this->findExpenseJournalEntry($expense);

            // 2. إنشاء قيد عكسي إذا وُجد القيد الأصلي
            if ($originalJournalEntry) {
                // إنشاء قيد عكسي جديد
                /*
                    **عمود مستخدمٍ يُكتب فيه معرّف موظّف.**

                    `created_by_employee` علاقتُه `belongsTo(User::class)`
                    رغم اسمه — يُقرأ كمعرّف **مستخدم**. وكان يُكتب فيه
                    `$user->employee_id`: للمستخدم رقم 10 موظّفٌ رقمه 11،
                    ولا مستخدم بالرقم 11. فتبحث الشاشة عن مستخدمٍ لا وجود
                    له وتطبع «غير محدد» في عمود «بواسطة».

                    وهو خطأٌ صامت: لا استثناء ولا مفتاح أجنبي يمنعه، ولا
                    يظهر إلّا حين يقرأ أحدٌ السطر ويسأل من فعل هذا.
                */
                $reversalEntry = JournalEntry::create([
                    'reference_type' => ReferenceType::EXPENSES,
                    'reference_number' => $expense->code.'-REV',
                    'date' => now()->toDateString(),
                    'description' => 'قيد عكسي - إلغاء سند صرف رقم: '.$expense->code
                        .' - ألغاه '.$user->name
                        .' في '.now()->format('Y-m-d H:i'),
                    'status' => 1, // approved
                    'linking_type' => LinkingType::SINGLE,
                    'created_by_employee' => $user->id,
                    'branch_id' => $expense->branch_id,
                    'approved_by_employee' => $user->id,
                ]);

                // جلب تفاصيل القيد الأصلي وعكسها
                $originalDetails = JournalEntryDetail::where('journal_entry_id', $originalJournalEntry->id)->get();

                foreach ($originalDetails as $detail) {
                    // عكس المدين والدائن
                    JournalEntryDetail::create([
                        'journal_entry_id' => $reversalEntry->id,
                        'account_id' => $detail->account_id,
                        'debit' => $detail->credit,  // المدين يصبح دائن والعكس
                        'credit' => $detail->debit,
                        'description' => 'عكس: '.($detail->description ?? ''),
                        // بلا نقل المركز يظهر التحميل في تقرير مراكز التكلفة
                        // ولا يظهر إلغاؤه
                        'cost_center_id' => $detail->cost_center_id,
                    ]);
                }

                // تحديث وصف القيد الأصلي للإشارة إلى الإلغاء
                $originalJournalEntry->update([
                    'description' => $originalJournalEntry->description.' (تم إلغاؤه - قيد عكسي: '.$reversalEntry->reference_number.')',
                ]);
            }

            // 3. تسجيل الإلغاء في السجلات
            OperationLog::record(
                'cancelled',
                'finance_log',
                $expense->id,
                sprintf('تم حذف سند صرف رقم **%s** بقيمة **%s** ريال وإنشاء قيد عكسي', $expense->code, number_format($expense->amount, 2))
            );

            // === عكس نقاط سند الصرف عند الإلغاء ===
            try {
                app(PointsService::class)->reverseByReference(Expense::class, $expense->id, 'إلغاء سند صرف رقم '.$expense->code);
            } catch (\Throwable $e) {
                $this->recordFailure($e, 'finance_log', 'expense_points_reversal', $expense);
            }

            // 4. حذف سند الصرف
            $expense->delete();

            DB::commit();

            if (request()->ajax() || request()->wantsJson()) {
                return response()->json(['success' => true, 'message' => 'تم حذف سند الصرف بنجاح وإنشاء قيد عكسي!']);
            }

            return redirect()->route('expenses.index')->with('success', 'تم حذف سند الصرف بنجاح وإنشاء قيد عكسي!');
        } catch (\Illuminate\Database\Eloquent\ModelNotFoundException $e) {
            /* سندٌ غير موجود — أشيعُ أسبابه نقرةٌ ثانية على «تأكيد الحذف»
               أو رجوعٌ لصفحةٍ قديمة. كانت الرسالةُ نصَّ الاستثناء
               («No query results for model …») ويُعاد المستخدم إلى صفحة
               السند نفسه فتظهر له ٤٠٤. ليس عطلاً فلا يُسجَّل في «سجلّ الأخطاء». */
            DB::rollback();
            $gone = 'هذا السند غير موجود — ربما حُذف مسبقاً.';

            if (request()->ajax() || request()->wantsJson()) {
                return response()->json(['success' => false, 'message' => $gone], 404);
            }

            return redirect()->route('expenses.index')->with('error', $gone);
        } catch (\Exception $e) {
            // يبلغ جدول «سجلّ الأخطاء»، لا ملفّ اللوق وحده
            OperationLog::failure($e, 'Account.Expenses', 'cancel');

            DB::rollback();
            Log::error('فشل في حذف سند الصرف: '.$e->getMessage().' - Stack: '.$e->getTraceAsString());

            if (request()->ajax() || request()->wantsJson()) {
                return response()->json(['success' => false, 'message' => 'حدث خطأ أثناء الحذف: '.$e->getMessage()], 500);
            }

            return back()->with('error', 'حدث خطأ أثناء الحذف: '.$e->getMessage());
        }
    }

    /**
     * تحديث سند الصرف وتعديل القيد المحاسبي المرتبط به.
     * Generated by Copilot
     *
     * @param  Request  $request  بيانات الطلب
     * @param  int  $id  معرف سند الصرف
     * @return RedirectResponse
     */
    public function update(Request $request, $id)
    {
        /*
            سندُ الراتب يُعدَّل بتعديل الصرفة نفسها لا بتعديل سندها: المبلغُ
            هنا صافي راتبٍ محسوبٍ من القسيمة والسلف والخصميات، وتغييرُه في
            السند وحده يفصله عن `payroll_runs.net_salary` وعن قيدَي
            الاستحقاق والصرف.
        */
        if ($payrollBlock = $this->payrollExpenseBlockReason($id)) {
            return back()->withInput()->with('error', $payrollBlock);
        }

        /*
            التحقّقُ والفترةُ والخزينة تُفحص قبل `beginTransaction()`، فرفضُها لا
            معاملةَ له — وكان `catch` يتراجع دائماً، فيُنهي معاملةَ من استدعى
            المتحكّمَ من داخل معاملته (واجهةُ التطبيق، والاختبارات) ويُثبِّت ما
            بعدها. يُتراجع عمّا فُتح هنا وحده.
        */
        $txLevel = DB::transactionLevel();

        try {
            // ✨ الموظفون مقيدون بسند صرف عام أو لعميل فقط — إلا من يملك
            // `data_scope_all` أو لا يديره أحد؛ هؤلاء يُسمح لهم بـ«لمورد» أيضاً
            // (كانت هذه الدالّة تقفل كل موظفٍ على «عام» فقط بصرف النظر عن
            // نوعه المُرسَل — حتى «لعميل» الذي تسمح به create()/store() —
            // فمطابقةُ نفس قاعدة store() هنا لا تشديدٌ إضافي)
            $authUser = Auth::user();
            $isEmployeeUser = $authUser && $authUser->isEmployee();
            /*
                كان النوعُ يُحوَّل صامتاً إلى «عام» ثم يُردّ بـ«يجب اختيار
                الحساب الثاني للقيد» — رسالةٌ لا تقول للمستخدم إنه لا يملك
                الصرف لمورد. والشاشة تُخفي الخيار أصلاً، فلا يصل إلا بطلبٍ
                مُعدٍّ يدوياً أو من تطبيقٍ لم يقرأ `can_expense_to_supplier`.
            */
            if ($isEmployeeUser && ! $this->canExpenseToSupplier($authUser)
                && $request->input('expense_type') === 'supplier') {
                throw ValidationException::withMessages([
                    'expense_type' => ['لا تملك صلاحية «سند صرف لمورد» — اختر سند صرف عام أو لعميل.'],
                ]);
            }

            // ✨ تنظيف القيم المتعارضة بحسب نوع السند
            $expenseType = $request->input('expense_type', 'general');
            if ($expenseType === 'general') {
                $request->merge(['supplier_id' => null]);
            } elseif ($expenseType === 'client') {
                // التصنيف يبقى: تصنيفُ المصروف لا يتعارض مع كون المستفيد عميلاً
                $request->merge(['supplier_id' => null]);
            } elseif ($expenseType === 'supplier') {
                $request->merge(['account_id' => null]);
            }

            // ✨ التحقق من البيانات بنفس قواعد store()
            $request->validate([
                'amount' => 'required|numeric|min:0.01',
                'date' => 'required|date',
                'expense_type' => 'required|in:general,client,supplier',
                'expenses_category_id' => 'required_unless:expense_type,client|nullable|exists:expenses_categories,id',
                'account_id' => 'required_if:expense_type,general|required_if:expense_type,client|nullable|exists:accounts,id',
                'supplier_id' => 'required_if:expense_type,supplier|nullable|exists:suppliers,id',
                'treasury_id' => 'required|exists:accounts,id',
                'cost_center_id' => 'nullable|exists:cost_centers,id',
                // الضريبة من «إعدادات الضرائب» — معرّفٌ غير موجود كان يبلغ الحفظ فيسقط 500
                'tax1' => 'nullable|exists:tax_sittings,id',
                'tax2' => 'nullable|exists:tax_sittings,id',
                'tax1_account_id' => 'nullable|exists:accounts,id',
                'tax2_account_id' => 'nullable|exists:accounts,id',
            ], [
                'expense_type.required' => 'نوع السند مطلوب',
                'account_id.required_if' => 'يجب اختيار الحساب الثاني للقيد',
                'supplier_id.required_if' => 'يجب اختيار المورد عند اختيار "سند صرف لمورد"',
            ]);

            // «إضافة ضرائب» بلا اختيار نوعها — لا يُحفظ السند
            TaxableDocument::assertChosenWhenAdded($request->all());

            // الفترة وشرط السحب بعد التحقّق — والتعديل قد ينقل السند إلى خزينةٍ أخرى
            $this->guardPeriod($request->input('date'));
            $this->guardTreasuryWithdraw($request->input('treasury_id'));

            // التحقق من أن الحساب المختار للسند العام طرفي (لا أبناء)
            if ($expenseType === 'general' && $request->filled('account_id')) {
                $accId = $request->input('account_id');
                if (Account::where('parent_id', $accId)->exists()) {
                    if ($request->ajax() || $request->wantsJson()) {
                        return response()->json([
                            'success' => false,
                            'message' => 'يجب اختيار حساب طرفي (بدون حسابات فرعية).',
                            'errors' => ['account_id' => ['يجب اختيار حساب طرفي.']],
                        ], 422);
                    }

                    return back()->withErrors(['account_id' => 'يجب اختيار حساب طرفي.'])->withInput();
                }

                // ✨ تحقق أمني: للموظفين - الحساب يجب أن يكون من حسابات المصروفات
                if ($isEmployeeUser) {
                    $allowedExpenseAccountIds = $this->getExpenseLeafAccounts()->pluck('id')->toArray();
                    if (! in_array((int) $accId, $allowedExpenseAccountIds, true)) {
                        if ($request->ajax() || $request->wantsJson()) {
                            return response()->json([
                                'success' => false,
                                'message' => 'يُسمح للموظفين فقط باختيار حسابات المصروفات.',
                                'errors' => ['account_id' => ['يجب اختيار حساب من شجرة المصروفات.']],
                            ], 422);
                        }

                        return back()->withErrors(['account_id' => 'يجب اختيار حساب من شجرة المصروفات.'])->withInput();
                    }
                }

                // بلا «إظهار كل الحسابات في سند الصرف»: حساباتُ التصنيف المختار وحدها
                if ($this->expenseAccountOutsideCategory($accId, $request->input('expenses_category_id'), Expense::find($id))) {
                    $message = 'هذا الحساب ليس من حسابات التصنيف المختار.';

                    if ($request->ajax() || $request->wantsJson()) {
                        return response()->json(['success' => false, 'message' => $message, 'errors' => ['account_id' => [$message]]], 422);
                    }

                    return back()->withErrors(['account_id' => $message])->withInput();
                }
            }

            /*
                نوع «عميل»: الحساب يجب أن يقع في شجرة المدينون.

                **ما كان**

                الشرط `empty($acc->client_id)` — أي أن يكون الحساب مرتبطاً
                بسجلّ عميل. وحين وُسّعت قائمة الاختيار لتشمل «المدينون
                وأبناءهم» كما تعرضها الشجرة المحاسبية، صارت الشاشة تعرض
                حساباتٍ يرفضها الخادم: يختار المستخدم حساباً من القائمة
                فيُردّ بـ«يجب اختيار حساب عميل صحيح» — والحساب من القائمة
                التي عرضتها الشاشة نفسها.

                **ما صار**

                الفحص يطابق ما تعرضه القائمة: العضوية في شجرة الحساب
                المضبوط تحت `clients_account` في «الحسابات المحاسبية».
                والحساب المرتبط بعميل يقع فيها بطبيعته، فلم يُفقد شيء من
                الضبط السابق.
            */
            if ($expenseType === 'client' && $request->filled('account_id')) {
                $accId = (int) $request->input('account_id');
                $scope = $this->clientsTreeAccountIds();

                $outsideTree = $scope !== null && ! in_array($accId, $scope, true);
                $isParent = Account::where('parent_id', $accId)->exists();
                // نفس نطاق القائمة (عرضاً) يُفرض هنا (حفظاً): معرّف عميلٍ
                // مُرسَل يدوياً خارج ما يراه هذا المستخدم — راجع getClientAccountsForUser()
                $outsideTeam = ! $isParent && ! $outsideTree && Account::whereKey($accId)->exists()
                    && ! $this->clientAccountAllowedForTeam($accId);

                if (! Account::whereKey($accId)->exists() || $outsideTree || $isParent || $outsideTeam) {
                    $message = match (true) {
                        $isParent => 'يجب اختيار حساب طرفي (بدون حسابات فرعية).',
                        $outsideTeam => 'هذا الحساب خارج نطاق عملائك.',
                        default => 'يجب اختيار حساب من شجرة المدينون.',
                    };

                    if ($request->ajax() || $request->wantsJson()) {
                        return response()->json([
                            'success' => false,
                            'message' => $message,
                            'errors' => ['account_id' => [$message]],
                        ], 422);
                    }

                    return back()->withErrors(['account_id' => $message])->withInput();
                }
            }

            DB::beginTransaction();

            // البحث عن سند الصرف المطلوب
            $expense = Expense::findOrFail($id);

            // التحقق من النطاق
            $this->authorizeCreatorScope($expense->created_by);

            // حفظ المبلغ القديم والخزينة القديمة لاستخدامها لاحقاً
            $oldAmount = $expense->amount;
            $oldTax1Amount = floatval($expense->tax1_amount) ?: 0;
            $oldTax2Amount = floatval($expense->tax2_amount) ?: 0;
            $oldTotalAmount = $oldAmount + $oldTax1Amount + $oldTax2Amount;
            $oldTreasuryId = $expense->treasury_id;
            $oldAccountId = $expense->account_id;

            // الحصول على الخزينة القديمة لاسترجاع المبلغ
            $oldTreasury = Account::find($oldTreasuryId);

            // تحديد الحساب المستخدم للقيد (حساب المصروفات أو حساب العميل)
            $oldAccountIdForJournal = $oldAccountId;
            if (! $oldAccountIdForJournal && $expense->expenses_category_id) {
                // البحث عن الحساب المرتبط بالتصنيف
                $category = ExpensesCategory::find($expense->expenses_category_id);
                if ($category) {
                    $existingAccount = Account::where('name', $category->name)
                        ->where('parent_id', 61)
                        ->first();
                    if ($existingAccount) {
                        $oldAccountIdForJournal = $existingAccount->id;
                    }
                }
            }

            // تحديث الحقول الأساسية
            $expense->code = $request->input('code');
            $expense->amount = $request->input('amount');
            $expense->description = $request->input('description');
            $expense->date = $request->input('date');
            $expense->unit_id = $request->input('unit_id');
            $expense->expenses_category_id = $request->input('expenses_category_id');
            $expense->supplier_id = $request->input('supplier_id');
            $expense->treasury_id = $request->input('treasury_id');
            $expense->account_id = $request->input('account_id');

            // تعبئة حقل صرف إلى تلقائياً إذا لم يتم إرساله
            $seller = $request->input('seller');
            if (empty($seller)) {
                // الأولوية: المورد أولاً
                if ($request->input('supplier_id')) {
                    $supplier = Supplier::find($request->input('supplier_id'));
                    $seller = $supplier ? $supplier->trade_name : null;
                }
                // ثانياً: الحساب (العميل)
                if (empty($seller) && $request->input('account_id')) {
                    $account = Account::find($request->input('account_id'));
                    $seller = $account ? $account->name : null;
                }
                // ثالثاً: التصنيف
                if (empty($seller) && $request->input('expenses_category_id')) {
                    $category = ExpensesCategory::find($request->input('expenses_category_id'));
                    $seller = $category ? $category->name : null;
                }
            }
            $expense->seller = $seller;

            $expense->is_recurring = $request->has('is_recurring') ? 1 : 0;
            $expense->recurring_frequency = $request->input('recurring_frequency');
            $expense->end_date = $request->input('end_date');
            $expense->tax1 = $request->input('tax1');
            $expense->tax2 = $request->input('tax2');
            $expense->tax1_account_id = $request->input('tax1_account_id');
            $expense->tax2_account_id = $request->input('tax2_account_id');

            /*
                وسمُ «سندٌ ضريبي» يُضبط من المدخلات لا بخانةٍ يؤشّرها
                المستخدم: ما يُترك لتذكّره يُنسى، فيخرج الإقرارُ ناقصاً
                بمقدار ما نُسي. والقاعدةُ في `TaxableDocument` — موضعٌ
                واحد لسندات الصرف والقبض والقيود.
            */
            $expense->is_taxable = TaxableDocument::fromVoucherInput($request->all());

            /*
                **الضريبةُ تُحسب هنا، لا تُؤخذ من الطلب.**

                كان `tax1_amount` و`total_amount` يُحفظان كما أرسلهما
                المتصفّح. فمن عبث بالطلب — أو أخطأ حسابُ الشاشة — حُفظ
                رقمُه كما هو، وخرج القيدُ والإقرارُ عليه.

                والحسابُ الآن من **معرّف الضريبة المحفوظ**: النسبةُ
                وطريقتُها من «إعدادات الضرائب» لا من الشاشة.

                **والطريقة المصرية:** الإجمالي يشمل الضريبة دائماً، و`amount`
                يُخزَّن **أساساً قبل الضريبة**. فإن كانت الضريبة «شاملة»
                (`included`) كان ما أدخله المستخدم حاملاً لها، فتُستخرَج منه
                ويُردّ المبلغُ إلى أساسه؛ وإن كانت «مضافة» (`excluded`) فما
                أدخله هو الأساسُ نفسه. وباستقرار `amount` على الأساس يصحّ
                سطرُ الحساب المقابل في القيد، ويصحّ مجموعُ التقارير:
                `total_amount = amount + الضريبة` في الحالَين.
            */
            $taxLines = TaxCalculator::forDocument($expense->amount, $expense->tax1, $expense->tax2);

            $expense->amount = $taxLines['base'];
            $expense->tax1_amount = $taxLines['tax1'];
            $expense->tax2_amount = $taxLines['tax2'];
            $expense->total_amount = $taxLines['total'];

            $costCenterId = $request->filled('cost_center_id')
                ? (int) $request->input('cost_center_id')
                : null;

            $expense->cost_centers_enabled = $costCenterId !== null ? 1 : 0;

            // تحديد الفرع - للموظف نستخدم فرعه دائماً، للمدير يمكنه الاختيار
            $user = Auth::user();
            $isAdmin = $user && ! $user->isEmployee();

            if ($isAdmin) {
                // المدير يمكنه اختيار الفرع، وإذا لم يختر نستخدم فرعه
                $branchId = $request->input('branch_id');
                if (empty($branchId)) {
                    $branchId = $user->branch_id ?? null;
                }
            } else {
                // الموظف: نستخدم فرعه دائماً بغض النظر عن القيمة المرسلة
                $branchId = $user->branch_id ?? null;
            }
            $expense->branch_id = $branchId;
            // طريقة الدفع من شاشة الإعدادات — اختيارية، فقد لا تُسجَّل
            $expense->payment_method_id = $request->input('payment_method_id') ?: null;

            // معالجة المرفقات المتعددة
            if ($request->hasFile('attachments')) {
                $existingAttachments = $expense->attachments ? json_decode($expense->attachments, true) : [];
                if (! is_array($existingAttachments)) {
                    $existingAttachments = $expense->attachments ? ['assets/uploads/expenses/'.$expense->attachments] : [];
                }

                foreach ($request->file('attachments') as $file) {
                    $fileName = $this->uploadImage('assets/uploads/expenses', $file);
                    $existingAttachments[] = 'assets/uploads/expenses/'.$fileName;
                }
                $expense->attachments = json_encode($existingAttachments);
            }

            // تحديد الخزينة الجديدة — نفس نطاق store(): يُقبل ما أُرسل بعد
            // التحقّق من أنه ضمن خزائن المستخدم (خزينته أو خزائن من يديرهم).
            $user = Auth::user();
            $newTreasuryId = $request->input('treasury_id');

            if (! empty($newTreasuryId)) {
                $this->assertTreasuryAccess((int) $newTreasuryId);
            }

            // إذا لم تُرسل خزينة جديدة، نستخدم خزينة الموظف أو الخزينة الرئيسية
            if (empty($newTreasuryId)) {
                if ($user && $user->employee_id) {
                    $TreasuryEmployee = TreasuryEmployee::where('employee_id', $user->employee_id)->first();
                    if ($TreasuryEmployee && $TreasuryEmployee->treasury_id) {
                        $newTreasuryId = $TreasuryEmployee->treasury_id;
                    } else {
                        $newTreasuryId = AccountingSettings::id('main_treasury', SystemAccountIds::MAIN_TREASURY);
                    }
                } else {
                    $newTreasuryId = AccountingSettings::id('main_treasury', SystemAccountIds::MAIN_TREASURY);
                }
            }

            $expense->treasury_id = $newTreasuryId;
            $newTreasury = Account::find($newTreasuryId);

            if (! $newTreasury) {
                throw new \Exception('لا توجد خزينة متاحة. يرجى التحقق من إعدادات الخزينة.');
            }

            // الإجمالي الجديد شامل الضرائب — كما حُسب عند الحفظ
            $newTax1Amount = (float) $expense->tax1_amount;
            $newTax2Amount = (float) $expense->tax2_amount;
            $newTotalAmount = (float) $expense->total_amount;

            // حساب الفرق في المبلغ (شامل الضرائب)
            $amountDifference = $newTotalAmount - $oldTotalAmount;

            // التحقق من رصيد الخزينة (الفرق إذا نفسها، أو المبلغ الكامل إذا تغيّرت)
            if ($oldTreasuryId == $newTreasuryId) {
                if ($amountDifference > 0 && $newTreasury->balance < $amountDifference) {
                    throw ValidationException::withMessages(['amount' => ['رصيد الخزينة غير كافٍ لتنفيذ عملية الصرف الإضافية.']]);
                }
            } else {
                if ($newTreasury->balance < $newTotalAmount) {
                    throw ValidationException::withMessages(['amount' => ['رصيد الخزينة الجديدة غير كافٍ لتنفيذ عملية الصرف.']]);
                }
            }

            // ⚠️ لا نحدِّث رصيد الخزينة يدوياً.
            // boot() في JournalEntryDetail يحدِّث الأرصدة تلقائياً عند حذف/إنشاء التفاصيل لاحقاً.

            // حفظ التحديثات
            $expense->save();

            // تسجيل النشاط في السجل
            OperationLog::record(
                'updated',
                'expense',
                $expense->id,
                sprintf('تم تعديل سند صرف رقم **%s** بقيمة **%s**', $expense->code, number_format($expense->amount, 2))
            );

            // ✨ المنطق الجديد: استخدم الحساب الذي اختاره المستخدم مباشرة
            $expenseType = $request->input('expense_type', 'general');
            $selectedAccountId = $request->input('account_id');
            $selectedSupplierId = $request->input('supplier_id');
            $selectedCategoryId = $request->input('expenses_category_id');

            $newAccountIdForJournal = null;
            $journalDescription = $expense->description ?: 'سند صرف';

            if ($expenseType === 'supplier') {
                // نفس علّة store() — لا عمود suppliers.account_id، والربط
                // عكسي (accounts.supplier_id) بلا حاجة لحفظ شيء على المورد
                $supplier = Supplier::with('account')->findOrFail($selectedSupplierId);
                if ($supplier->account) {
                    $newAccountIdForJournal = $supplier->account->id;
                } else {
                    $supplierAccount = new Account;
                    $supplierAccount->name = $supplier->trade_name ?? trim(($supplier->first_name ?? '').' '.($supplier->last_name ?? ''));
                    $supplierAccount->type = 'sub';
                    $supplierAccount->balance = 0;
                    $supplierAccount->is_active = 1;
                    $supplierAccount->code = $this->generateNextCode();
                    $supplierAccount->supplier_id = $supplier->id;
                    $supplierAccount->parent_id = AccountingSettings::id('suppliers', SystemAccountIds::SUPPLIERS);
                    $supplierAccount->balance_type = 'credit';
                    $supplierAccount->save();
                    $newAccountIdForJournal = $supplierAccount->id;
                }
                $journalDescription = 'سند صرف لمورد: '.($supplier->trade_name ?? ($supplier->first_name ?? ''));
            } elseif ($expenseType === 'client') {
                $clientAccount = Account::findOrFail($selectedAccountId);
                $newAccountIdForJournal = $clientAccount->id;
                $journalDescription = 'سند صرف لعميل: '.$clientAccount->name;
            } else {
                // ✨ سند صرف عام - الحساب المحدد مباشرة (طرفي)
                $expenseAccount = Account::findOrFail($selectedAccountId);
                $newAccountIdForJournal = $expenseAccount->id;
                $categoryName = $selectedCategoryId
                    ? (ExpensesCategory::find($selectedCategoryId)->name ?? '')
                    : '';
                $journalDescription = 'سند صرف'.($categoryName ? ' - '.$categoryName : '')
                    .': '.$expenseAccount->name
                    .($expense->description ? ' ('.$expense->description.')' : '');
            }

            if (! $newAccountIdForJournal) {
                throw new \Exception('لم يتم تحديد الحساب الثاني للقيد.');
            }

            /*
                **سطرا الضريبة لا يجوز أن يسقطا في التعديل أيضاً.**

                كانت الخزينة تُحمَّل دائناً بالإجمالي شاملاً الضريبة، بينما
                سطرُ الضريبة المدين مشروطٌ باختيار المستخدم حساباً لها. فمن
                عدّل سنداً ضريبياً ولم يختر الحساب خرج قيدُه **غير متوازن**
                بمقدار الضريبة — وهو ما أُصلح في الإنشاء وبقي هنا.

                والحساب يُلتمس من «الحسابات المحاسبية» (`vat_paid`) متى لم
                يُختر، وإلا رُمي الخطأ: مستندٌ يُرفض خيرٌ من دفترٍ يفسد.
            */
            $resolveTaxAccount = function ($chosen) {
                if ($chosen && Account::whereKey($chosen)->exists()) {
                    return (int) $chosen;
                }

                $fallback = AccountingSettings::id('vat_paid', SystemAccountIds::VAT_PAID);

                if (! $fallback || ! Account::whereKey($fallback)->exists()) {
                    throw new \RuntimeException(
                        'تعذّر تحديد حساب الضريبة: اختر حساباً للضريبة في السند، '
                        .'أو اضبط «ضريبة المشتريات المدفوعة» في الحسابات المحاسبية.'
                    );
                }

                return (int) $fallback;
            };

            // ✨ البحث عن القيد المحاسبي - reference_id موثوق + fallback آمن
            $journalEntry = $this->findExpenseJournalEntry($expense);

            if ($journalEntry) {
                // ✨ تحديث بيانات القيد + ضمان وجود reference_id (للقيود القديمة قد لا يكون موجوداً)
                $journalEntry->update([
                    'date' => $expense->date,
                    'description' => $journalDescription,
                    'created_by_employee' => Auth::id(),
                    'branch_id' => $expense->branch_id,
                    'reference_id' => $expense->id,
                    'reference_number' => $expense->code,
                ]);

                // حذف تفاصيل القيد القديمة وإنشاء جديدة
                JournalEntryDetail::where('journal_entry_id', $journalEntry->id)->delete();

                // إنشاء تفاصيل القيد الجديدة - حساب الخزينة (دائن بالإجمالي شامل الضرائب)
                JournalEntryDetail::create([
                    'journal_entry_id' => $journalEntry->id,
                    'account_id' => $newTreasury->id,
                    'description' => 'صرف مبلغ من الخزينة',
                    'debit' => 0,
                    'credit' => $newTotalAmount,
                    'is_debit' => false,
                ]);

                // إنشاء تفاصيل القيد الجديدة - الحساب المحدد (مدين بالمبلغ الأساسي)
                JournalEntryDetail::create([
                    'journal_entry_id' => $journalEntry->id,
                    'account_id' => $newAccountIdForJournal,
                    'description' => $journalDescription,
                    'debit' => $expense->amount,
                    'credit' => 0,
                    'is_debit' => true,
                    'cost_center_id' => $costCenterId,
                ]);

                // سطرا الضريبة — الحساب يُلتمس من الإعدادات متى لم يُختر
                foreach ([
                    [$newTax1Amount, $expense->tax1_account_id, 'الضريبة الأولى'],
                    [$newTax2Amount, $expense->tax2_account_id, 'الضريبة الثانية'],
                ] as [$taxAmount, $chosenAccount, $taxLabel]) {
                    if ($taxAmount <= 0) {
                        continue;
                    }

                    JournalEntryDetail::create([
                        'journal_entry_id' => $journalEntry->id,
                        'account_id' => $resolveTaxAccount($chosenAccount),
                        'description' => 'ضريبة القيمة المضافة - '.$taxLabel,
                        'debit' => $taxAmount,
                        'credit' => 0,
                        'is_debit' => true,
                        'cost_center_id' => $costCenterId,
                    ]);
                }
            } else {
                // إذا لم يوجد قيد، ننشئ قيد جديد - مع ربط reference_id
                $journalEntry = JournalEntry::create([
                    'reference_number' => $expense->code,
                    'reference_id' => $expense->id,
                    'date' => $expense->date,
                    'description' => $journalDescription,
                    'status' => 1,
                    'currency' => $expense->documentCurrency(),
                    'created_by_employee' => Auth::id(),
                    'reference_type' => ReferenceType::EXPENSES,
                    'linking_type' => LinkingType::SINGLE,
                    'branch_id' => $expense->branch_id,
                ]);

                // تفاصيل القيد - حساب الخزينة (دائن بالإجمالي شامل الضرائب)
                JournalEntryDetail::create([
                    'journal_entry_id' => $journalEntry->id,
                    'account_id' => $newTreasury->id,
                    'description' => 'صرف مبلغ من الخزينة',
                    'debit' => 0,
                    'credit' => $newTotalAmount,
                    'is_debit' => false,
                ]);

                // تفاصيل القيد - الحساب المحدد (مدين بالمبلغ الأساسي)
                JournalEntryDetail::create([
                    'journal_entry_id' => $journalEntry->id,
                    'account_id' => $newAccountIdForJournal,
                    'description' => $journalDescription,
                    'debit' => $expense->amount,
                    'credit' => 0,
                    'is_debit' => true,
                    'cost_center_id' => $costCenterId,
                ]);

                // سطرا الضريبة — الحساب يُلتمس من الإعدادات متى لم يُختر
                foreach ([
                    [$newTax1Amount, $expense->tax1_account_id, 'الضريبة الأولى'],
                    [$newTax2Amount, $expense->tax2_account_id, 'الضريبة الثانية'],
                ] as [$taxAmount, $chosenAccount, $taxLabel]) {
                    if ($taxAmount <= 0) {
                        continue;
                    }

                    JournalEntryDetail::create([
                        'journal_entry_id' => $journalEntry->id,
                        'account_id' => $resolveTaxAccount($chosenAccount),
                        'description' => 'ضريبة القيمة المضافة - '.$taxLabel,
                        'debit' => $taxAmount,
                        'credit' => 0,
                        'is_debit' => true,
                        'cost_center_id' => $costCenterId,
                    ]);
                }
            }

            DB::commit();

            // إذا كان الطلب AJAX
            if ($request->ajax() || $request->wantsJson()) {
                return response()->json([
                    'success' => true,
                    'message' => 'تم تحديث سند الصرف بنجاح!',
                    'redirect' => route('expenses.show', $id),
                ]);
            }

            return redirect()->route('expenses.show', $id)->with('success', 'تم تحديث سند صرف بنجاح!');
        } catch (ValidationException $e) {
            // خطأ تحقّق — كان يسقط في catch (\Exception) أدناه فيُردّ 500
            // «حدث خطأ» بدل رسالة الحقل. يُعاد رميه ليعرضه Laravel كما هو.
            while (DB::transactionLevel() > $txLevel) {
                DB::rollBack();
            }

            throw $e;
        } catch (\Exception $e) {
            // يبلغ جدول «سجلّ الأخطاء»، لا ملفّ اللوق وحده
            OperationLog::failure($e, 'Account.Expenses', 'update');

            while (DB::transactionLevel() > $txLevel) {
                DB::rollBack();
            }
            Log::error('خطأ في تحديث سند صرف: '.$e->getMessage());

            if ($request->ajax() || $request->wantsJson()) {
                if ($e instanceof PlanLimitExceededException) {
                    return response()->json(['success' => false, 'message' => $e->getMessage(), 'code' => 'PLAN_LIMIT_REACHED'], 402);
                }

                return response()->json([
                    'success' => false,
                    'message' => 'حدث خطأ أثناء تحديث سند الصرف: '.$e->getMessage(),
                ], 500);
            }

            return back()
                ->with('error', 'حدث خطأ أثناء تحديث سند الصرف: '.$e->getMessage())
                ->withInput();
        }
    }

    public function show($id)
    {
        $expense = Expense::with(['branch', 'createdBy.branch', 'treasury', 'Supplier', 'expenses_category', 'account'])->findOrFail($id);

        // التحقق من الصلاحية - المدير يمكنه عرض أي سند، الموظف فقط سنداته
        $this->authorizeCreatorScope($expense->created_by);

        // ✨ جلب القيد المحاسبي المرتبط بالمصروف
        // أولوية لـ reference_id (موثوق) - يضمن عدم التقاط قيود orphan لسندات سابقة بنفس الكود
        $journalEntry = $this->findExpenseJournalEntry($expense);

        // جلب سجلات النشاطات المرتبطة بسند الصرف فقط
        $logs = ModelsLog::where('type', 'expense')
            ->where('type_id', $id)
            ->whereHas('expense') // التأكد من وجود علاقة مع سند الصرف
            ->with('user')
            ->orderBy('created_at', 'desc')
            ->get()
            ->groupBy(function ($item) {
                return $item->created_at->format('Y-m-d');
            });

        // الوصول إلى هنا يعني أن authorizeCreatorScope() أعلاه أجاز العرض
        // بالفعل — تكفي الصلاحية وحدها. لا صلاحيات النظام القديم
        // (`finance_edit_delete_own/all_expenses`)
        $canEdit = auth()->user()->hasRolePermission('account.expenses.edit');

        return view('account::finance.expenses.show', compact('expense', 'logs', 'journalEntry', 'canEdit'));
    }

    /**
     * @param  int  $id  معرف سند الصرف المراد تعديله
     * @return View
     */
    public function edit($id)
    {
        $expense = Expense::findOrFail($id);

        // التحقق من النطاق
        $this->authorizeCreatorScope($expense->created_by);

        $user = auth()->user();

        // جلب التصنيفات
        $expenses_categories = ExpensesCategory::select('id', 'name')->get();

        // جلب الموردين
        $suppliers = Supplier::all();

        // جلب الخزائن — خزائنه هو أو خزائن من يديرهم، ثم ما يجوز له السحب
        // منه؛ وخزينةُ السند الحالية تبقى معروضةً وإن مُنعت
        $treasuries = $this->withdrawableTreasuryAccounts($expense->treasury_id);

        // ✨ حسابات العملاء فقط - فلترة صارمة
        $accounts = $this->getClientAccountsForUser($user);

        // ✨ حسابات المصروفات الطرفية للسند العام
        [$expenseLeafAccounts, $restrictExpenseAccounts, $categoryAccountMap] = $this->expenseAccountsForUser($user, $expense);

        // جلب الخزينة الرئيسية أو خزينة الموظف
        $MainTreasury = null;
        $treasury_id = null;

        if ($user && $user->employee_id) {
            $TreasuryEmployee = TreasuryEmployee::where('employee_id', $user->employee_id)->first();

            if ($TreasuryEmployee && $TreasuryEmployee->treasury_id) {
                $MainTreasury = Account::where('id', $TreasuryEmployee->treasury_id)->first();
                $treasury_id = $TreasuryEmployee->treasury_id;
            } else {
                $MainTreasury = Account::find(AccountingSettings::id('main_treasury', SystemAccountIds::MAIN_TREASURY));
                $treasury_id = $MainTreasury->id ?? null;
            }
        } else {
            $MainTreasury = Account::find(AccountingSettings::id('main_treasury', SystemAccountIds::MAIN_TREASURY));
            $treasury_id = $MainTreasury->id ?? null;
        }

        // جلب الضرائب
        $taxs = TaxSitting::all();

        // جلب إعدادات الحساب
        $account_setting = AccountSetting::where('user_id', $user->id)->first();

        // جلب الفروع
        $branches = Branch::all();

        /*
            المركز لا يُقرأ من السند — لا عمود له فيه — بل من أوّل سطرٍ
            مدينٍ في قيده. وبدونه تُعيد شاشةُ التعديل الحقلَ فارغاً في كل
            مرّة، فيُمسح المركزُ عند أوّل حفظٍ بلا قصد.
        */
        $currentCostCenterId = optional(
            JournalEntryDetail::whereIn(
                'journal_entry_id',
                JournalEntry::where('reference_type', ReferenceType::EXPENSES)
                    ->where('reference_id', $expense->id)
                    ->select('id')
            )->whereNotNull('cost_center_id')->first()
        )->cost_center_id;

        return view('account::finance.expenses.edit', compact(
            'currentCostCenterId',
            'expense',
            'expenses_categories',
            'taxs',
            'treasuries',
            'accounts',
            'expenseLeafAccounts',
            'suppliers',
            'MainTreasury',
            'treasury_id',
            'account_setting',
            'branches',
            'restrictExpenseAccounts',
            'categoryAccountMap'
        ));
    }

    /**
     * حذف سند صرف.
     *
     * **ما كان**
     *
     * `$expense->delete()` وحدها. تُمحى ورقةُ السند ويبقى **قيدُه المحاسبي
     * قائماً** يحمّل المصروف ويُنقص الخزينة إلى الأبد، بلا مستندٍ يفسّره.
     * فتُقرأ التقارير مصروفاً لا سندَ له، ولا سبيل إلى معرفة مصدره.
     *
     * وكان في الملفّ نفسه `cancel()` يفعل الصواب: يُرحّل قيداً عكسياً ثم
     * يحذف السند. فالشاشة تعرض زرَّين أحدهما سليم والآخر يُفسد الدفاتر،
     * والفرق بينهما غير ظاهر للمستخدم.
     *
     * **ما صار**
     *
     * الحذف هو الإلغاء نفسه: قيدٌ عكسي ثم حذف. لا يبقى أثرٌ محاسبي بلا
     * مستند، ولا يضيع تاريخُ ما جرى.
     */
    public function delete($id)
    {
        return $this->cancel($id);
    }

    public function uploadImage($folder, $image)
    {
        $fileExtension = $image->getClientOriginalExtension();
        $fileName = time().rand(1, 99).'.'.$fileExtension;
        $image->move($folder, $fileName);

        return $fileName;
    } // end of uploadImage

    public function print($id, $type = 'normal')
    {
        $expense = Expense::findOrFail($id);

        if ($type == 'thermal') {
            // عرض نسخة حرارية
            return view('account::finance.expenses.print_thermal', compact('expense'));
        } else {
            // عرض نسخة عادية
            return view('account::finance.expenses.print_normal', compact('expense'));
        }
    }
